// The one base creature for the whole cast: a boxy paper critter with eyes only and stubby limbs.
// Cast members differ by colour, accessory and name pill. (x, y) is the ground point under the body.
import React from 'react';
import {useCurrentFrame} from 'remotion';
import {C} from '../tokens';
import {Disc, Paper, Pill, Slab, bob} from '../paper/kit';

export type Expr = 'idle' | 'sleep' | 'shock' | 'happy' | 'worried' | 'blink' | 'squint';
export type Acc = 'none' | 'postCap' | 'monocle' | 'headphones' | 'visor' | 'cap' | 'hardhat' | 'beret' | 'glasses' | 'headset' | 'bowtie';
// Hat-like accessories push the name pill up.
const HAT: Acc[] = ['postCap', 'headphones', 'cap', 'hardhat', 'beret'];

export const Critter: React.FC<{
  x: number; y: number; size?: number; color?: string; shade?: string;
  expr?: Expr; acc?: Acc; tag?: string; tagColor?: string;
  armR?: number; armRAngle?: number; armL?: number; armLAngle?: number;   // reach 0–1, angle deg (negative = up)
  lean?: number; lift?: number; face?: 1 | -1; tape?: boolean; phase?: number; idle?: boolean;
  holdR?: React.ReactNode;   // drawn at the tip of the right arm
  accColor?: string; accShade?: string;   // colour for cap / hardhat / beret / headset / bowtie (role colour for agents)
}> = ({x, y, size = 240, color = C.hero, shade = C.heroLo, expr = 'idle', acc = 'none', tag, tagColor = C.purple, accColor, accShade, armR = 0, armRAngle = 0, armL = 0, armLAngle = 0, lean = 0, lift = 0, face = 1, tape, phase = 0, idle = true, holdR}) => {
  const f = useCurrentFrame();
  const u = size / 10;
  const b = idle ? bob(f, 36, 3, phase) : 0;
  const bLag = idle ? bob(f - 2, 36, 3, phase) : 0;
  const blink = expr === 'idle' && (f + Math.round(phase * 7)) % 83 < 3;
  const bodyW = 10 * u, bodyH = 7 * u, legH = 2.2 * u;
  const top = -legH - bodyH;   // body top, relative to ground
  const e = expr === 'blink' || blink ? 'blink' : expr;
  const eyeW = u * (e === 'shock' ? 1.3 : 1), eyeH = u * (e === 'shock' ? 2.1 : 1.6);
  const eyes = [[3 * u, 2 * u], [6 * u, 2 * u]];
  const arm = (side: 1 | -1, reach: number, ang: number) => {
    const len = 2.3 * u + reach * 5 * u;
    const ax = side === 1 ? bodyW - 0.4 * u : 0.4 * u;
    return (
      <div style={{position: 'absolute', left: ax, top: 3.4 * u, width: 0, height: 0, rotate: `${side === 1 ? ang : -ang}deg`}}>
        <Slab x={side === 1 ? 0 : -len} y={-0.7 * u} w={len} h={1.4 * u} color={color} shade={shade} shadeH={0.3} r={3} />
        {side === 1 && holdR ? <div style={{position: 'absolute', left: len, top: 0}}>{holdR}</div> : null}
      </div>
    );
  };
  return (
    <div style={{position: 'absolute', left: x, top: y, width: 0, height: 0, scale: `${face} 1`}}>
      <div style={{position: 'absolute', left: 0, top: -lift + b, width: 0, height: 0, rotate: `${lean}deg`, transformOrigin: '0 0'}}>
        <div style={{position: 'absolute', left: -bodyW / 2, top: top, width: bodyW, height: bodyH + legH}}>
          <Paper lift={5}>
            {/* legs: four stubs */}
            {[1.2, 3.3, 5.7, 7.8].map((lx, i) => (
              <Slab key={i} x={lx * u} y={bodyH - 0.3 * u} w={1 * u} h={legH + 0.3 * u} color={color} shade={shade} shadeH={0.35} r={2} />
            ))}
            {arm(-1, armL, armLAngle)}
            <Slab x={0} y={0} w={bodyW} h={bodyH} color={color} shade={shade} shadeH={0.16} r={4} />
            {arm(1, armR, armRAngle)}
            {/* eyes */}
            {eyes.map(([ex, ey], i) =>
              e === 'sleep' || e === 'blink' || e === 'happy' ? (
                <div key={i} style={{position: 'absolute', left: ex - 0.15 * u, top: ey + (e === 'happy' ? 0.3 * u : 0.8 * u), width: 1.3 * u, height: 0.28 * u, background: C.ink, borderRadius: e === 'happy' ? '50% 50% 0 0' : 2}} />
              ) : (
                <div key={i} style={{position: 'absolute', left: ex + (e === 'worried' ? (i ? -0.2 : 0.2) * u : 0) + (1 * u - eyeW) / 2, top: ey + (e === 'squint' ? 0.5 * u : 0), width: eyeW, height: e === 'squint' ? 0.6 * u : eyeH, background: C.ink, borderRadius: 2}} />
              ),
            )}
            {e === 'shock' ? <div style={{position: 'absolute', left: 4.4 * u, top: 4.5 * u, width: 1.1 * u, height: 1.1 * u, borderRadius: '50%', background: C.ink}} /> : null}
            {e === 'happy' ? <div style={{position: 'absolute', left: 4 * u, top: 4.4 * u, width: 2 * u, height: 0.3 * u, background: C.ink, borderRadius: 3}} /> : null}
            {tape ? <Slab x={2.6 * u} y={4.1 * u} w={4.8 * u} h={1.3 * u} color={C.tape} rot={-6} r={2} style={{opacity: 0.92}} /> : null}
            {/* accessories */}
            {acc === 'postCap' ? (
              <>
                <Slab x={1.2 * u} y={-1.9 * u} w={7.6 * u} h={2.1 * u} color={C.cap} shade={C.capLo} shadeH={0.3} r="40% 40% 6px 6px" />
                <Slab x={5.4 * u} y={-0.1 * u} w={4.6 * u} h={0.7 * u} color={C.capLo} r={3} />
                <Slab x={4.3 * u} y={-1.5 * u} w={1.3 * u} h={1.1 * u} color={C.brass} shade={C.brassLo} r={3} />
              </>
            ) : null}
            {acc === 'monocle' ? (
              <>
                <div style={{position: 'absolute', left: 5.5 * u, top: 1.5 * u, width: 2 * u, height: 2 * u, borderRadius: '50%', border: `${0.35 * u}px solid ${C.brass}`, boxSizing: 'border-box', background: 'rgba(255,255,255,0.12)'}} />
                <div style={{position: 'absolute', left: 6.4 * u, top: 3.5 * u, width: 0.2 * u, height: 2.4 * u, background: C.brassLo, rotate: '-12deg'}} />
                <Slab x={3.4 * u} y={6.3 * u} w={3.2 * u} h={1.3 * u} color={C.nogo} shade={C.nogoDim} r="40%" />
              </>
            ) : null}
            {acc === 'headphones' ? (
              <>
                <div style={{position: 'absolute', left: 0.6 * u, top: -1.6 * u, width: 8.8 * u, height: 4 * u, borderRadius: '50% 50% 0 0', border: `${0.6 * u}px solid ${C.board}`, borderBottom: 'none', boxSizing: 'border-box'}} />
                <Slab x={-0.4 * u} y={1.4 * u} w={1.5 * u} h={2.4 * u} color={C.board} r={6} />
                <Slab x={8.9 * u} y={1.4 * u} w={1.5 * u} h={2.4 * u} color={C.board} r={6} />
              </>
            ) : null}
            {acc === 'visor' ? <Slab x={0.8 * u} y={-0.8 * u} w={9.6 * u} h={1.2 * u} color={accColor ?? C.go} shade={accShade ?? C.goDim} shadeH={0.4} r={4} /> : null}
            {acc === 'cap' ? (
              // "you": blue baseball cap, brim forward (to the right)
              <>
                <Slab x={1.4 * u} y={-2.1 * u} w={7.2 * u} h={2.4 * u} color={accColor ?? C.cap} shade={accShade ?? C.capLo} shadeH={0.28} r="50% 50% 4px 4px" />
                <Slab x={6.2 * u} y={0} w={4.4 * u} h={0.75 * u} color={accShade ?? C.capLo} r="3px 40% 40% 3px" />
                <Disc x={5 * u} y={-2 * u} d={0.9 * u} color={accShade ?? C.capLo} />
              </>
            ) : null}
            {acc === 'hardhat' ? (
              <>
                <Slab x={1 * u} y={-2.3 * u} w={8 * u} h={2.6 * u} color={accColor ?? C.amber} shade={accShade ?? C.amberDim} shadeH={0.22} r="50% 50% 3px 3px" />
                <Slab x={0.2 * u} y={0} w={9.6 * u} h={0.7 * u} color={accShade ?? C.amberDim} r={3} />
                <Slab x={4.6 * u} y={-2.2 * u} w={0.8 * u} h={2.2 * u} color={accShade ?? C.amberDim} r={2} />
              </>
            ) : null}
            {acc === 'beret' ? (
              <>
                <Slab x={1.6 * u} y={-1.5 * u} w={7.6 * u} h={1.9 * u} color={accColor ?? C.ink} shade={accShade ?? '#000'} shadeH={0.3} r="55% 45% 40% 40%" rot={-6} />
                <Slab x={4.8 * u} y={-2.1 * u} w={0.6 * u} h={0.9 * u} color={accColor ?? C.ink} r={3} />
              </>
            ) : null}
            {acc === 'glasses' ? (
              <>
                {[[2.4, 1.6], [5.6, 1.6]].map(([gx, gy], i) => (
                  <div key={i} style={{position: 'absolute', left: gx * u, top: gy * u, width: 2.1 * u, height: 2.1 * u, borderRadius: '50%', border: `${0.32 * u}px solid ${C.ink}`, boxSizing: 'border-box', background: 'rgba(255,255,255,0.14)'}} />
                ))}
                <div style={{position: 'absolute', left: 4.4 * u, top: 2.5 * u, width: 1.3 * u, height: 0.3 * u, background: C.ink}} />
              </>
            ) : null}
            {acc === 'headset' ? (
              <>
                <div style={{position: 'absolute', left: 0.4 * u, top: -1.2 * u, width: 9.2 * u, height: 3.4 * u, borderRadius: '50% 50% 0 0', border: `${0.45 * u}px solid ${C.board}`, borderBottom: 'none', boxSizing: 'border-box'}} />
                <Slab x={-0.3 * u} y={1.6 * u} w={1.3 * u} h={2 * u} color={accColor ?? C.board} r={6} />
                <div style={{position: 'absolute', left: 0.3 * u, top: 3.4 * u, width: 3.2 * u, height: 0.3 * u, background: C.board, rotate: '18deg', transformOrigin: '0 0'}} />
                <Disc x={3.5 * u} y={4.5 * u} d={0.8 * u} color={C.board} />
              </>
            ) : null}
            {acc === 'bowtie' ? (
              <>
                <Slab x={3.5 * u} y={6 * u} w={1.5 * u} h={1.4 * u} color={accColor ?? C.nogo} r="40% 10% 10% 40%" />
                <Slab x={5 * u} y={6 * u} w={1.5 * u} h={1.4 * u} color={accColor ?? C.nogo} r="10% 40% 40% 10%" />
                <Disc x={5 * u} y={6.7 * u} d={0.8 * u} color={accShade ?? C.nogoDim} />
              </>
            ) : null}
          </Paper>
        </div>
        {tag ? (
          <div style={{position: 'absolute', left: 0, top: top - (HAT.includes(acc) ? 3.3 : 1.6) * u + (bLag - b), scale: `${face} 1`}}>
            <Pill x={0} y={0} text={tag} bg={tagColor} size={Math.max(24, 0.13 * size)} />
          </div>
        ) : null}
      </div>
    </div>
  );
};

// Fonts from local files in public/fonts/: the exact woff2 files @remotion/google-fonts used to fetch at render time.
// Two problems this fixes:
//  1. Network: every render tab fetched the fonts from fonts.gstatic.com, so a Wi-Fi blip failed the whole render.
//  2. Banner jitter: TapeBanner sizes its text with fitText(). A tab that measured before the font arrived cached the
//     fallback width, so the banner jumped between two sizes from frame to frame (whichever tab rendered it).
// Every face loads under one delayRender; `fontsReady` resolves when all are in document.fonts. Measure text only after it.
import {cancelRender, continueRender, delayRender, staticFile} from 'remotion';

const LATIN = 'U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD';
const LATIN_EXT = 'U+0100-02BA, U+02BD-02C5, U+02C7-02CC, U+02CE-02D7, U+02DD-02FF, U+0304, U+0308, U+0329, U+1D00-1DBF, U+1E00-1E9F, U+1EF2-1EFF, U+2020, U+20A0-20AB, U+20AD-20C0, U+2113, U+2C60-2C7F, U+A720-A7FF';
const FACES: [family: string, weight: string, file: string][] = [
  ['Archivo Black', '400', 'archivo-black-400'],
  ['Fraunces', '900', 'fraunces-900'],
  ['Inter', '800', 'inter-800'],
  ['JetBrains Mono', '700', 'jetbrains-mono-700'],
];

let loaded = false;
const handle = delayRender('Loading local fonts (public/fonts)');
/** Resolves once every kit font is loaded and added to document.fonts. */
export const fontsReady: Promise<void> = Promise.all(
  FACES.flatMap(([family, weight, file]) => [['latin', LATIN], ['latin-ext', LATIN_EXT]].map(async ([sub, range]) => {
    const face = new FontFace(family, `url(${staticFile(`fonts/papercut/fonts/${file}-${sub}.woff2`)}) format('woff2')`, {weight, style: 'normal', unicodeRange: range, display: 'block'});
    document.fonts.add(await face.load());
  })),
).then(() => {
  loaded = true;
  continueRender(handle);
}).catch((err) => cancelRender(err));

/** True once fontsReady has resolved (synchronous check for components). */
export const fontsLoaded = () => loaded;

// Backdrops: 24 paper-diorama sets (1080x1920 JPEGs in public/bg/backdrops/) to use instead of <Room>, so each scene can sit in its own place.
// Layout contract for every set: floor line near y 1420 (measured per set in BACKDROPS), calm middle band for props and UI, calm top for the banner,
// plain bottom for captions, light from the top-left, no people or text baked in. Stand props and critters on BACKDROPS[name].floorY.
// Catalogue with descriptions and bestFor: public/bg/backdrops/backdrops.json (also listed in lib/papercut/CATALOG.md).
import React from 'react';
import {AbsoluteFill, Img, staticFile} from 'remotion';

// Every backdrop name with its measured floor line (px y at 1080x1920) and mood (day, night, warm, cool). Props and critters stand on floorY.
export const BACKDROPS = {
  'gamer-bedroom': {floorY: 1379, mood: 'night'},
  'server-room': {floorY: 1435, mood: 'cool'},
  'home-office-day': {floorY: 1432, mood: 'day'},
  'cafe': {floorY: 1481, mood: 'warm'},
  'startup-office': {floorY: 1289, mood: 'day'},
  'rooftop-day': {floorY: 1501, mood: 'day'},
  'city-street-night': {floorY: 1430, mood: 'night'},
  'garage-workshop': {floorY: 1452, mood: 'warm'},
  'library': {floorY: 1414, mood: 'warm'},
  'classroom': {floorY: 1519, mood: 'day'},
  'lab': {floorY: 1469, mood: 'cool'},
  'stage-spotlight': {floorY: 1438, mood: 'warm'},
  'kitchen': {floorY: 1530, mood: 'day'},
  'park-day': {floorY: 1419, mood: 'day'},
  'art-gallery': {floorY: 1420, mood: 'day'},
  'gallery-lobby': {floorY: 1420, mood: 'cool'},
  'courtroom': {floorY: 1450, mood: 'warm'},
  'bank-vault': {floorY: 1450, mood: 'cool'},
  'warehouse': {floorY: 1450, mood: 'warm'},
  'mission-control': {floorY: 1440, mood: 'night'},
  'airport-gate': {floorY: 1440, mood: 'day'},
  'subway-platform': {floorY: 1440, mood: 'night'},
  'diner': {floorY: 1440, mood: 'warm'},
  'bedroom-day': {floorY: 1450, mood: 'day'},
} as const;

// Union of the backdrop names, for typing a scene's `backdrop` prop.
export type BackdropName = keyof typeof BACKDROPS;

// Backdrop: full-frame generated set (object-fit cover), a drop-in for <Room>. Optional `tint` multiplies a colour over it, `dim` (0-1) darkens it toward black.
export const Backdrop: React.FC<{name: BackdropName; tint?: string; dim?: number}> = ({name, tint, dim = 0}) => (
  <AbsoluteFill>
    <Img src={staticFile(`images/papercut/bg/backdrops/${name}.jpg`)} style={{position: 'absolute', inset: 0, width: '100%', height: '100%', objectFit: 'cover'}} />
    {tint ? <AbsoluteFill style={{backgroundColor: tint, mixBlendMode: 'multiply'}} /> : null}
    {dim > 0 ? <AbsoluteFill style={{backgroundColor: '#000', opacity: Math.min(1, dim)}} /> : null}
  </AbsoluteFill>
);

// Camera moves for papercut sets: parallax orbit (OrbitCamera + Depth layers), foreground pass, rack focus, snap zoom, pull-back reveal and freeze frame.
// A fake camera moving through a paper diorama; all motion from useCurrentFrame(). Moves transform the whole frame, so the banner zone (y < 420) and the caption band (y 1420-1580) move too: keep key props and faces out of both.
import React, {createContext, useContext, useId} from 'react';
import {AbsoluteFill, Easing, Freeze, interpolate, random, useCurrentFrame} from 'remotion';
import {C, FONT, H, W} from '../tokens';
import {Disc, GRAIN, Paper, Slab, Boil} from './kit';
import {Cable, PlugHead} from '../props/cable';

const clamp = {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'} as const;
const rad = (d: number) => (d * Math.PI) / 180;

// ---------- motion blur: a smooth zoom smear ----------
// The sharp current frame sits underneath. On top, n sub-frame samples of the same transform are averaged (copy i of n at time
// f - shutter * (n-1-i)/(n-1), opacity 1/(i+1)), a CSS blur sized to the zoom speed melts the gaps between the copies, and a radial
// mask keeps the middle of the zoom sharp so only the outer ring smears, like a real zoom blur.
const Smear: React.FC<{n: number; shutter: number; blur: number; center: [number, number]; at: (t: number) => string; origin: string; children: React.ReactNode}> = ({n, shutter, blur, center, at, origin, children}) => {
  const f = useCurrentFrame();
  const cur = {transform: at(f), transformOrigin: origin};
  if (n <= 1) return <AbsoluteFill style={cur}>{children}</AbsoluteFill>;
  const mask = `radial-gradient(circle at ${center[0]}px ${center[1]}px, transparent 0px, transparent 100px, #000 460px)`;
  return (
    <>
      <AbsoluteFill style={cur}>{children}</AbsoluteFill>
      <AbsoluteFill style={{filter: `blur(${blur.toFixed(1)}px)`, WebkitMaskImage: mask, maskImage: mask}}>
        {Array.from({length: n}).map((_, i) => {
          const t = f - (shutter * (n - 1 - i)) / (n - 1);
          return <AbsoluteFill key={i} style={{transform: at(t), transformOrigin: origin, opacity: i === 0 ? 1 : 1 / (i + 1)}}>{children}</AbsoluteFill>;
        })}
      </AbsoluteFill>
    </>
  );
};
// How many samples a move needs this frame: none when it is slow, more as it speeds up. `speed` = scale change per frame.
const samplesFor = (speed: number, on: boolean) => (!on ? 1 : speed > 0.05 ? 12 : speed > 0.02 ? 7 : speed > 0.008 ? 4 : 1);
const blurFor = (speed: number) => Math.min(12, speed * 85);

// ---------- 1. parallax orbit ----------
const PERSP = 1600;
// One camera state shared with every <Depth> layer: yaw/pitch (deg), pan (px), dolly (translateZ px), an extra zoom, and a world track
// (side / lift, px) that each layer follows by 1 + (z - focus) * parallax, so far layers travel less than near ones.
type Cam = {
  yaw: number; pitch: number; panX: number; panY: number; dolly: number; zoom: number; side: number; lift: number; parallax: number;
  span: number; focus: number; origin: [number, number]; yawMax: number; panMax: number; dollyEnd: number; zoomEnd: number;
};
const CamCtx = createContext<Cam | null>(null);
const baseCam = (o: Partial<Cam> & Pick<Cam, 'span' | 'focus' | 'origin'>): Cam => ({
  yaw: 0, pitch: 0, panX: 0, panY: 0, dolly: 0, zoom: 1, side: 0, lift: 0, parallax: 0, yawMax: 0, panMax: 0, dollyEnd: 0, zoomEnd: 1, ...o,
});

// Parallax orbit: the camera arcs `yaw` degrees (16) around the focal plane while dollying to `push`, so <Depth z> layers separate. `origin` = pivot px (near the floor line), `depth` = layer spacing, `drift` = pan px.
export const OrbitCamera: React.FC<{dur: number; yaw?: number; drift?: [number, number]; push?: number; focus?: number; depth?: number; origin?: [number, number]; children: React.ReactNode}> = ({dur, yaw = 16, drift = [0, 0], push = 1.08, focus = 0.45, depth = 800, origin = [540, 1000], children}) => {
  const f = useCurrentFrame();
  const t = interpolate(f, [0, Math.max(1, dur)], [0, 1], {...clamp, easing: Easing.bezier(0.4, 0, 0.3, 1)});
  const cam = baseCam({
    yaw: (t - 0.5) * yaw, panX: drift[0] * t, panY: drift[1] * t, dolly: PERSP * (1 - 1 / push) * t,
    span: depth, focus, origin, yawMax: Math.abs(yaw) / 2, panMax: Math.max(Math.abs(drift[0]), Math.abs(drift[1])),
  });
  return <CamCtx.Provider value={cam}><AbsoluteFill>{children}</AbsoluteFill></CamCtx.Provider>;
};

// Depth layer in <OrbitCamera>: z 0 = backdrop (auto-oversized to cover), ~0.5 = props and cast, 1 = foreground. Lay each out at normal screen positions; the camera adds the parallax. Outside an OrbitCamera it is a plain fill.
export const Depth: React.FC<{z: number; cover?: boolean; children: React.ReactNode}> = ({z, cover, children}) => {
  const cam = useContext(CamCtx);
  if (!cam) return <AbsoluteFill>{children}</AbsoluteFill>;
  const tz = (z - cam.focus) * cam.span;
  const comp = (PERSP - tz) / PERSP;   // cancels the perspective shrink so the layer keeps its authored size at rest
  const sy = Math.sin(rad(cam.yawMax));
  // overscan so the layer's edges never show: its sideways shift, the far edge's foreshortening, a little vertical foreshortening
  const need = Math.abs(tz) * sy + cam.panMax + 540 * sy * (540 / PERSP) * 1.4 + 24;
  let bleed = (cover ?? z <= 0.1) ? 1.035 + need / 540 : 1;
  // a dolly zoom shrinks far layers: start them oversized by the shrink they will reach
  const endScale = ((PERSP - tz) / Math.max(60, PERSP - tz - cam.dollyEnd)) * cam.zoomEnd;
  if ((cover ?? z <= 0.1) && endScale < 1) bleed *= 1.03 / endScale;
  const trav = 1 + (z - cam.focus) * cam.parallax;   // how much of the world track this layer follows
  const tx = cam.panX - cam.side * trav, ty = cam.panY - cam.lift * trav;
  const d = Math.min(tz + cam.dolly, PERSP - 60);
  return (
    <AbsoluteFill style={{
      transformOrigin: `${cam.origin[0]}px ${cam.origin[1]}px`,
      transform: `perspective(${PERSP}px) translate(${tx}px, ${ty}px) rotateX(${cam.pitch}deg) rotateY(${cam.yaw}deg) translateZ(${d}px) scale(${comp * bleed * cam.zoom})`,
    }}>
      {children}
    </AbsoluteFill>
  );
};

// ---------- 2. foreground pass ----------
// A cut-paper monstera leaf, heart-shaped with slits cut in from the edge. Layers: a dark underside piece offset below, a light left
// half and darker right half, a lighter vein piece (midrib and side veins), and a stem. Drawn in a 760 x 1000 box; the stem joins at (380, 980).
const SLIT_Y = [800, 650, 510, 380];   // where each slit's tip sits, left of the midrib (the right side mirrors it)
const VEIN_Y = [790, 640, 505, 375, 270];
const BLADE = 'M380 880 C330 960 140 960 70 760 C10 600 60 300 200 130 C280 60 340 40 380 20 C420 40 480 60 560 130 C700 300 750 600 690 760 C620 960 430 960 380 880 Z';
const wedge = (tx: number, ty: number, side: 1 | -1) => {
  const dx = -0.82 * side, dy = -0.57, nx = -dy * side, ny = dx * side, L = 420, hw = 30;
  const pt = (px: number, py: number) => `${px.toFixed(1)},${py.toFixed(1)}`;
  const ex = tx + dx * L, ey = ty + dy * L;
  return `${pt(tx, ty)} ${pt(ex + nx * hw, ey + ny * hw)} ${pt(ex - nx * hw, ey - ny * hw)}`;
};
const MonsteraLeaf: React.FC<{light: string; dark: string; under: string; vein: string}> = ({light, dark, under, vein}) => {
