      {/* the scratch: a cut zigzag across the disc, plus three screech marks */}
      <div style={{position: 'absolute', inset: 0, transformOrigin: `${cx}px ${cy}px`, transform: `scale(${pop}) rotate(-12deg)`, opacity: t < 1 ? 0 : 1}}>
        <Paper lift={3}>
          <svg width={W} height={H} viewBox={`0 0 ${W} ${H}`} style={{position: 'absolute', left: 0, top: 0}}>
            <polygon fill={C.creamHi} points={`${cx - 92},${cy - 26} ${cx - 34},${cy - 6} ${cx - 54},${cy + 2} ${cx + 6},${cy + 22} ${cx - 10},${cy + 26} ${cx + 94},${cy + 50} ${cx + 12},${cy + 8} ${cx + 34},${cy} ${cx - 28},${cy - 22} ${cx - 8},${cy - 26}`} />
          </svg>
          {[-58, -18, 22].map((a, i) => (
            <Slab key={a} x={cx + 78} y={cy - 4 - i * 0} w={44 - i * 6} h={9} r={4} color={C.creamHi} rot={a} style={{transformOrigin: `-78px 4px`}} />
          ))}
        </Paper>
      </div>
    </>
  );
};

// Meme beat: holds the child on frame `at` (Freeze), desaturates, darkens the edges, then slaps on a torn paper `label` (at x, y) with a stamp bounce and a record-scratch mark (left|right). Pair with SFX `scratch` at `at`.
export const FreezeFrame: React.FC<{at: number; label?: string; x?: number; y?: number; rot?: number; size?: number; mark?: 'left' | 'right' | false; children: React.ReactNode}> = ({at, label, x = 540, y = 1190, rot = -3, size: sizeProp, mark = 'right', children}) => {
  const f = useCurrentFrame();
  const t = f - at;
  const on = t >= 0;
  const sat = interpolate(t, [0, 4], [1, 0.55], clamp);
  const punch = interpolate(t, [0, 3], [1, 1.035], {...clamp, easing: Easing.out(Easing.cubic)});
  const vig = interpolate(t, [0, 6], [0, 1], clamp);
  const flash = interpolate(t, [0, 1, 3], [0.4, 0.4, 0], clamp);
  const lt = t - 3;   // the label lands three frames after the freeze
  const size = sizeProp ?? (label ? Math.max(46, Math.min(92, 880 / (0.52 * label.length))) : 80);
  const lw = label ? size * 0.52 * label.length + 100 : 0;
  const sc = interpolate(lt, [0, 2, 4, 7], [2.4, 0.9, 1.06, 1], {...clamp, easing: Easing.out(Easing.quad)});
  const lrot = rot + interpolate(lt, [0, 7], [-9, 0], {...clamp, easing: Easing.out(Easing.cubic)});
  return (
    <AbsoluteFill>
      <AbsoluteFill style={{filter: on ? `saturate(${sat.toFixed(3)}) contrast(1.05)` : undefined, transform: `scale(${punch})`}}>
        <Freeze frame={at} active={on}>{children}</Freeze>
      </AbsoluteFill>
      {on ? <AbsoluteFill style={{background: 'radial-gradient(ellipse at 50% 48%, rgba(0,0,0,0) 38%, rgba(0,0,0,0.62) 100%)', opacity: vig}} /> : null}
      {on ? <AbsoluteFill style={{backgroundColor: '#fff', opacity: flash}} /> : null}
      {on && label && lt >= 0 ? (
        <Boil amp={1.4} rot={0.25} seed="freeze">
          <div style={{position: 'absolute', left: x, top: y, transform: `translate(-50%, -50%) rotate(${lrot}deg) scale(${sc})`}}>
            <div style={{position: 'absolute', inset: 0, translate: '10px 12px', rotate: '2.2deg', backgroundColor: C.tag, backgroundImage: `url(${GRAIN})`, backgroundSize: '420px', backgroundBlendMode: 'multiply', filter: 'url(#torn)'}} />
            <div style={{
              position: 'relative', backgroundColor: C.cream, backgroundImage: `url(${GRAIN})`, backgroundSize: '520px', backgroundBlendMode: 'multiply',
              padding: '16px 48px 26px', fontFamily: FONT.caption, fontWeight: 900, fontSize: size, lineHeight: 1.05, color: C.ink, whiteSpace: 'nowrap',
              filter: 'url(#torn) drop-shadow(3px 9px 10px rgba(0,0,0,0.5))',
            }}>{label}</div>
            {[{left: -26, rotate: '-34deg'}, {right: -26, rotate: '34deg'}].map((p, i) => (
              <div key={i} style={{position: 'absolute', top: -14, width: 92, height: 36, background: C.tape, opacity: 0.8, filter: 'url(#torn)', ...p}} />
            ))}
          </div>
          {mark ? <RecordMark cx={mark === 'left' ? Math.max(110, x - lw / 2 + 30) : Math.min(W - 110, x + lw / 2 - 20)} cy={y - 112} t={lt - 2} /> : null}
        </Boil>
      ) : null}
    </AbsoluteFill>
  );
};

// ---------- 7. dolly zoom ----------

// Dolly zoom for the REALISATION beat ("oh no"): the subject layer (z = focus) holds its size, near layers swell and the backdrop shrinks and spreads. Build it from <Depth z> layers. `strength` 1.5; <1 reverses.
export const DollyZoom: React.FC<{dur: number; at?: number; strength?: number; grow?: number; focus?: number; depth?: number; origin?: [number, number]; children: React.ReactNode}> = ({dur, at = 0, strength = 1.5, grow = 0.04, focus = 0.45, depth = 1100, origin = [540, 1100], children}) => {
  const f = useCurrentFrame();
  const t = interpolate(f, [at, at + Math.max(1, dur)], [0, 1], {...clamp, easing: Easing.bezier(0.5, 0, 0.25, 1)});
  const Z = 1 + (strength - 1) * t;   // the subject plane scales by Z from the dolly, then 1/Z from the zoom: it stays put
  const cam = baseCam({
    dolly: PERSP * (1 - 1 / Z), zoom: (1 + grow * t) / Z, span: depth, focus, origin,
    dollyEnd: PERSP * (1 - 1 / strength), zoomEnd: (1 + grow) / strength,
  });
  return <CamCtx.Provider value={cam}><AbsoluteFill>{children}</AbsoluteFill></CamCtx.Provider>;
};

// ---------- 8. crab track ----------
// A horizontal blur that follows the speed of a track; `amount` is the blur in px (0 = none).
const TrackBlur: React.FC<{axis: 'x' | 'y'; amount: number; children: React.ReactNode}> = ({axis, amount, children}) => {
  const id = useId().replace(/:/g, '');
  const on = amount > 0.4;
  return (
    <AbsoluteFill style={{filter: on ? `url(#tb${id})` : undefined}}>
      {on ? <svg width={0} height={0} style={{position: 'absolute'}}><filter id={`tb${id}`} x="-5%" y="-5%" width="110%" height="110%"><feGaussianBlur stdDeviation={axis === 'x' ? `${amount.toFixed(1)} 0` : `0 ${amount.toFixed(1)}`} /></filter></svg> : null}
      {children}
    </AbsoluteFill>
  );
};

// Total frames a CrabTrack takes: a hold at every stop and a move between stops.
export const crabFrames = (stops: number[], hold = 14, move = 10) => stops.length * hold + (stops.length - 1) * move;

// Crab track (a flat side-on track) for LISTS, lineups and comparisons: slides along a set wider than the frame, easing to each x in `stops` (world px) and holding `hold` frames. Put layers in <Depth> (z 0.45 = items).
export const CrabTrack: React.FC<{stops: number[]; hold?: number; move?: number; at?: number; parallax?: number; focus?: number; blur?: boolean; children: React.ReactNode}> = ({stops, hold = 14, move = 10, at = 0, parallax = 0.5, focus = 0.45, blur = true, children}) => {
  const f = useCurrentFrame();
  const sideAt = (ff: number) => {
    const k = Math.max(0, ff - at), period = hold + move, i = Math.min(stops.length - 1, Math.floor(k / period));
    if (i >= stops.length - 1) return stops[stops.length - 1] - 540;
    const u = interpolate(k - i * period, [hold, hold + move], [0, 1], {...clamp, easing: Easing.bezier(0.6, 0, 0.2, 1)});
    return stops[i] + (stops[i + 1] - stops[i]) * u - 540;   // each stop puts its item on the frame's centre line
  };
  const cam = baseCam({side: sideAt(f), parallax, span: 1000, focus, origin: [540, 960]});
  const speed = Math.abs(sideAt(f) - sideAt(f - 1));
  return <CamCtx.Provider value={cam}><TrackBlur axis="x" amount={blur ? Math.min(18, speed * 0.13) : 0}>{children}</TrackBlur></CamCtx.Provider>;
};

// ---------- 9. crane ----------

// Crane for SCALE reveals and "meanwhile, below": a vertical move through a tall set (layers in <Depth>, world y = screen y at the top). `drop` descends `height` px through dollhouse floors; `rise` climbs and tilts to a high angle.
export const Crane: React.FC<{dur: number; height: number; mode?: 'rise' | 'drop'; at?: number; pitch?: number; parallax?: number; focus?: number; blur?: boolean; origin?: [number, number]; children: React.ReactNode}> = ({dur, height, mode = 'drop', at = 0, pitch, parallax = 0.35, focus = 0.45, blur = true, origin = [540, 1000], children}) => {
  const f = useCurrentFrame();
  const e = (ff: number) => interpolate(ff, [at, at + Math.max(1, dur)], [0, 1], {...clamp, easing: Easing.bezier(0.45, 0, 0.2, 1)});
  const liftAt = (ff: number) => (mode === 'drop' ? height * e(ff) : height * (1 - e(ff)));
  const tilt = (pitch ?? (mode === 'rise' ? 14 : 0)) * (mode === 'rise' ? e(f) : 0);
  const cam = baseCam({lift: liftAt(f), pitch: tilt, parallax, span: 1000, focus, origin});
  const speed = Math.abs(liftAt(f) - liftAt(f - 1));
  return <CamCtx.Provider value={cam}><TrackBlur axis="y" amount={blur ? Math.min(20, speed * 0.1) : 0}>{children}</TrackBlur></CamCtx.Provider>;
};

// ---------- 10. POV mask ----------
const ring = (outer: string, inner: string) => `${outer}${inner}`;
const circleD = (cx: number, cy: number, r: number) => `M${cx - r} ${cy}a${r} ${r} 0 1 0 ${2 * r} 0a${r} ${r} 0 1 0 ${-2 * r} 0Z`;
const keyholeD = (x: number, y: number, s: number) => {
  const r = 200 * s, cy = y - 110 * s, a = 66 * s, yi = cy + Math.sqrt(r * r - a * a), yb = yi + 560 * s;
  return `M${x - a} ${yi}A${r} ${r} 0 1 1 ${x + a} ${yi}L${x + 170 * s} ${yb}L${x - 170 * s} ${yb}Z`;
};
const binoD = (x: number, y: number, s: number) => {
  const r = 320 * s, d = 205 * s, h = Math.sqrt(r * r - d * d);
  return `M${x} ${y - h}A${r} ${r} 0 1 0 ${x} ${y + h}A${r} ${r} 0 1 0 ${x} ${y - h}Z`;
};
const roundRectD = (x: number, y: number, w: number, h: number, r: number) =>
  `M${x + r} ${y}H${x + w - r}A${r} ${r} 0 0 1 ${x + w} ${y + r}V${y + h - r}A${r} ${r} 0 0 1 ${x + w - r} ${y + h}H${x + r}A${r} ${r} 0 0 1 ${x} ${y + h - r}V${y + r}A${r} ${r} 0 0 1 ${x + r} ${y}Z`;
const FRAME_D = `M-2000 -2000H4000V4000H-2000Z`;
const clip = (d: string) => `path(evenodd, "${d}")`;

// POV mask for SPY and PRIVACY beats: the child is seen through a paper keyhole, lens, binoculars or phone viewfinder (`kind`) in a dark surround, with handheld sway and a crosshair `reticle`. (x, y) = view centre; `at` = raise frame.
export const PovMask: React.FC<{kind?: 'keyhole' | 'lens' | 'binoculars' | 'phone'; x?: number; y?: number; size?: number; reticle?: boolean; at?: number; sway?: number; zoom?: number; children: React.ReactNode}> = ({kind = 'binoculars', x = 540, y = 900, size = 1, reticle = true, at = 0, sway = 1, zoom = 1.12, children}) => {
  const f = useCurrentFrame();
  const k = interpolate(f, [at, at + 10], [2.4, 1], {...clamp, easing: Easing.out(Easing.cubic)});   // raising it: the hole shrinks onto the view
  const s = size * k;
  const sx = Math.sin(f / 11) * 9 * sway * (k > 1.05 ? 0 : 1), sy = Math.cos(f / 13) * 7 * sway * (k > 1.05 ? 0 : 1);
  const cx = x + sx, cy = y + sy;
  const inner = kind === 'keyhole' ? keyholeD(cx, cy, s) : kind === 'lens' ? circleD(cx, cy, 360 * s) : kind === 'binoculars' ? binoD(cx, cy, s) : roundRectD(cx - 430 * s, cy - 640 * s, 860 * s, 1280 * s, 64 * s);
  const view = interpolate(k, [1, 2.4], [zoom, 1], clamp);
  const trim = 24 * s;
  const rim = kind === 'keyhole' ? keyholeD(cx, cy, s * 1.16) : kind === 'lens' ? circleD(cx, cy, 360 * s + trim) : kind === 'binoculars' ? binoD(cx, cy, s * 1.06) : roundRectD(cx - 430 * s - 16, cy - 640 * s - 16, 860 * s + 32, 1280 * s + 32, 76 * s);
  const rimColor = kind === 'keyhole' || kind === 'lens' ? '#C89B4A' : '#2B2833';
  const paper = {backgroundImage: `url(${GRAIN})`, backgroundSize: '520px', backgroundBlendMode: 'multiply'} as const;
  return (
    <AbsoluteFill>
      <AbsoluteFill style={{transformOrigin: `${x}px ${y}px`, transform: `translate(${-sx * 0.7}px, ${-sy * 0.7}px) scale(${view})`}}>{children}</AbsoluteFill>
      {/* the rim, then the dark surround; its shadow falls into the hole so the cut reads as thick paper */}
      <div style={{position: 'absolute', inset: 0, filter: 'drop-shadow(0px 5px 7px rgba(0,0,0,0.55))'}}>
        <div style={{position: 'absolute', inset: 0, clipPath: clip(ring(rim, inner)), backgroundColor: rimColor, ...paper}} />
      </div>
      <div style={{position: 'absolute', inset: 0, filter: 'drop-shadow(0px 7px 12px rgba(0,0,0,0.6))'}}>
        <div style={{position: 'absolute', inset: 0, clipPath: clip(ring(FRAME_D, rim)), backgroundColor: '#15131B', ...paper}} />
      </div>
      {kind === 'lens' ? (
        <div style={{position: 'absolute', inset: 0, rotate: '42deg', transformOrigin: `${cx}px ${cy}px`}}>
          <Paper lift={7}>
            <Slab x={cx + 360 * s + trim - 10} y={cy - 38 * s} w={460 * s} h={76 * s} color="#7F5231" shade="#5E3B22" shadeH={0.4} hi="#95653F" hiH={0.2} r={`${38 * s}px`} />
          </Paper>
        </div>
      ) : null}
      {kind === 'phone' ? <PhoneUi cx={cx} cy={cy} s={s} f={f} /> : null}
      {reticle ? <Reticle cx={cx} cy={cy} s={s} focusBox={kind === 'phone'} /> : null}
    </AbsoluteFill>
  );
};

// paper crosshair (or a viewfinder focus box)
const Reticle: React.FC<{cx: number; cy: number; s: number; focusBox: boolean}> = ({cx, cy, s, focusBox}) => {
  const c = focusBox ? '#F5C542' : '#E8DFD3', t = 6;
  const arm = (x0: number, y0: number, w: number, h: number) => <Slab key={`${x0}${y0}`} x={x0} y={y0} w={w} h={h} r={2} color={c} style={{opacity: 0.9}} />;
  if (focusBox) {
    const b = 130 * s;
    const sq = (x0: number, y0: number, w: number, h: number) => arm(x0, y0, w, h);
    return <Paper lift={2}>{[sq(cx - b, cy - b, b * 2, t), sq(cx - b, cy + b - t, b * 2, t), sq(cx - b, cy - b, t, b * 2), sq(cx + b - t, cy - b, t, b * 2)]}</Paper>;
  }
  const L = 110 * s, g = 34 * s;
  return <Paper lift={2}>{[arm(cx - g - L, cy - t / 2, L, t), arm(cx + g, cy - t / 2, L, t), arm(cx - t / 2, cy - g - L, t, L), arm(cx - t / 2, cy + g, t, L), <Disc key="d" x={cx} y={cy} d={10} color={c} />]}</Paper>;
};

// phone viewfinder furniture: corner brackets and a blinking REC dot
const PhoneUi: React.FC<{cx: number; cy: number; s: number; f: number}> = ({cx, cy, s, f}) => {
  const w = 430 * s, h = 640 * s, m = 34, L = 74, t = 8, c = '#F3EEE6';
  const corner = (sx: 1 | -1, sy: 1 | -1) => (
    <React.Fragment key={`${sx}${sy}`}>
      <Slab x={sx > 0 ? cx + w - m - L : cx - w + m} y={sy > 0 ? cy + h - m - t : cy - h + m} w={L} h={t} r={2} color={c} />
      <Slab x={sx > 0 ? cx + w - m - t : cx - w + m} y={sy > 0 ? cy + h - m - L : cy - h + m} w={t} h={L} r={2} color={c} />
    </React.Fragment>
  );
  return (
    <>
      <Paper lift={2}>{[corner(1, 1), corner(-1, 1), corner(1, -1), corner(-1, -1)]}</Paper>
      {Math.floor(f / 8) % 2 === 0 ? <Paper lift={2}><Disc x={cx - w + m + 30} y={cy - h + m + 64} d={26} color="#E04030" /></Paper> : null}
      <div style={{position: 'absolute', left: cx - w + m + 56, top: cy - h + m + 44, fontFamily: FONT.label, fontWeight: 800, fontSize: 28, color: c, letterSpacing: '0.08em'}}>REC</div>
    </>
  );
};

// ---------- 11. time ramp ----------
const smooth = (u: number) => { const k = Math.min(1, Math.max(0, u)); return k * k * (3 - 2 * k); };

// Time ramp (speed ramp / bullet time) for the DRAMATIC beat: remaps the child's clock. `segments` = [{until (outer frame), rate}]: 0.2 = slow-mo, 0 = frozen, >1 = fast with a trail; 1 after the last. `start` = inner frame at 0.
export const TimeRamp: React.FC<{segments: {until: number; rate: number}[]; start?: number; trail?: boolean; push?: number; children: React.ReactNode}> = ({segments, start = 0, trail = true, push = 0.05, children}) => {
  const f = useCurrentFrame();
  const E = 6;   // frames to blend from one rate to the next
  const rateAt = (t: number) => {
    let r = segments[0]?.rate ?? 1;
    for (let j = 0; j < segments.length; j++) r += ((segments[j + 1]?.rate ?? 1) - segments[j].rate) * smooth((t - segments[j].until) / E + 0.5);
    return r;
  };
  const clockAt = (t: number) => {   // integrate the rate curve from outer 0 to t
    let g = start;
    for (let u = 0; u < t; u += 0.5) g += rateAt(u + 0.25) * Math.min(0.5, t - u);
    return Math.max(0, g);
  };
  const r = rateAt(f);
  const slow = Math.min(1, Math.max(0, 1 - r));
  const zoom = 1 + push * slow;
  const n = trail && r > 1.3 ? 5 : 1;
  const shutter = 0.9;
  return (
    <AbsoluteFill style={{transform: `scale(${zoom})`, transformOrigin: '50% 55%', filter: slow > 0.05 ? `saturate(${(1 - 0.25 * slow).toFixed(3)})` : undefined}}>
      {Array.from({length: n}).map((_, i) => {
        const t = n === 1 ? f : f - (shutter * (n - 1 - i)) / (n - 1);
        return <AbsoluteFill key={i} style={{opacity: i === 0 ? 1 : 1 / (i + 1)}}><Freeze frame={clockAt(t)}>{children}</Freeze></AbsoluteFill>;
      })}
    </AbsoluteFill>
  );
};

// ---------- 12. dutch tilt, tilt shift ----------

// Dutch tilt for "things going wrong": the frame rolls to `deg` (10) with a back-ease snap from `at`, then judders on twos. Scaled up so the rotated frame still covers the canvas (a big crop at 1080 x 1920, so keep key props central).
export const DutchTilt: React.FC<{deg?: number; at?: number; judder?: number; children: React.ReactNode}> = ({deg = 10, at = 0, judder = 1, children}) => {
  const f = useCurrentFrame();
  const k = interpolate(f, [at, at + 7], [0, 1], {...clamp, easing: Easing.out(Easing.back(2.2))});
  const step = Math.floor(f / 2);
  const j = (random(`dj${step}`) * 2 - 1) * judder, j2 = (random(`dk${step}`) * 2 - 1) * judder, j3 = (random(`dl${step}`) * 2 - 1) * judder;
  const a = Math.abs(deg) + 1.2 * judder;
  const cover = Math.cos(rad(a)) + (H / W) * Math.sin(rad(a));
  const live = Math.min(1, Math.max(0, k));
  return (
    <AbsoluteFill style={{transform: `translate(${j2 * 6 * live}px, ${j3 * 5 * live}px) rotate(${deg * k + j * 0.9 * live}deg) scale(${1 + (cover - 1) * live})`}}>{children}</AbsoluteFill>
  );
};

// Tilt shift for MINIATURE scale ("a tiny paper world"): blurs the top and bottom bands so the diorama reads as a toy model, and lifts saturation. `focus` = sharp band centre (0-1), `band` = its height, `blur` = px at the edges.
export const TiltShift: React.FC<{focus?: number; band?: number; blur?: number; sat?: number; children: React.ReactNode}> = ({focus = 0.5, band = 0.3, blur = 14, sat = 1.15, children}) => {
  const pct = (v: number) => `${Math.min(100, Math.max(0, v * 100)).toFixed(1)}%`;
  const lo = focus - band / 2, hi = focus + band / 2;
  const mask = (soft: number, edge: number) => `linear-gradient(to bottom, #000 0%, #000 ${pct(lo - edge)}, transparent ${pct(lo + soft)}, transparent ${pct(hi - soft)}, #000 ${pct(hi + edge)}, #000 100%)`;
  const m1 = mask(0.03, 0.14), m2 = mask(0.0, 0.07);
  const layer = (b: number, m: string, key: string) => <AbsoluteFill key={key} style={{filter: `blur(${b}px) saturate(${sat})`, WebkitMaskImage: m, maskImage: m, transform: `scale(${1 + b * 0.005})`}}>{children}</AbsoluteFill>;
  return (
    <AbsoluteFill>
      <AbsoluteFill style={{filter: `saturate(${sat}) contrast(1.04)`}}>{children}</AbsoluteFill>
      {layer(blur * 0.45, m1, 'a')}
      {layer(blur, m2, 'b')}
    </AbsoluteFill>
  );
};

// ---------- 13. focus hunt ----------
// The lens "hunting" for focus: a blur envelope with keys at 0, 4, 8, 13, 18 of 18 frames = radius 0, 8, 18, 5, 0, mapped to CSS px (peak ~12.6).
const huntBlur = (k: number) => 0.7 * interpolate(k, [0, 4 / 18, 8 / 18, 13 / 18, 1], [0, 8, 18, 5, 0], clamp);

// Focus pulse, the hunt alone on a static shot: it goes soft and snaps back over `dur` frames (18) from `at`. For REVEALS and emphasis (a number lands, a prop is named) without moving the camera.
export const FocusPulse: React.FC<{at: number; dur?: number; children: React.ReactNode}> = ({at, dur = 18, children}) => {
  const f = useCurrentFrame();
  const b = huntBlur(Math.min(1, Math.max(0, (f - at) / Math.max(2, dur))));
  return <AbsoluteFill style={{filter: b > 0.05 ? `blur(${b.toFixed(2)}px)` : undefined, transform: b > 0.05 ? `scale(${1 + b * 0.0045})` : undefined}}>{children}</AbsoluteFill>;
};

// Focus hunt for REVEALS: pushes in on a number or key prop at (x, y) from 1x to 1+`amount` (1 = 2x) over `dur` frames (30) with a hard ease, and the lens hunts for focus part-way through (starts at 10/30 of dur, lasts 18/30).
export const FocusHunt: React.FC<{at: number; dur?: number; amount?: number; x?: number; y?: number; children: React.ReactNode}> = ({at, dur = 30, amount = 1, x = 540, y = 960, children}) => {
  const f = useCurrentFrame();
  const z = interpolate(f, [at, at + Math.max(1, dur)], [0, 1], {...clamp, easing: Easing.bezier(0.8, 0, 0.2, 1)});
  const start = at + Math.round((10 * dur) / 30), len = Math.max(2, Math.round((18 * dur) / 30));
  return (
    <AbsoluteFill style={{transformOrigin: `${x}px ${y}px`, transform: `scale(${1 + amount * z})`}}>
      <FocusPulse at={start} dur={len}>{children}</FocusPulse>
    </AbsoluteFill>
  );
};

// ---------- handheld ----------
// Handheld camera for lit-by-fire and tense scenes: a slow, deterministic multi-sine drift (x, y, roll) plus a faint breathing scale. `amount` = px of drift, `roll` = deg, `rate` = frames per drift cycle; `settleAt` = the frame it eases (10 frames) to a locked-off shot. Scaled up just enough that the drifting frame still covers the canvas, so keep key props out of the outer ~15 px.
export const Handheld: React.FC<{amount?: number; roll?: number; rate?: number; settleAt?: number; children: React.ReactNode}> = ({amount = 6, roll = 0.35, rate = 54, settleAt, children}) => {
  const f = useCurrentFrame();
  const k = settleAt === undefined ? 1 : 1 - interpolate(f, [settleAt, settleAt + 10], [0, 1], {...clamp, easing: Easing.inOut(Easing.cubic)});
  const w = (ph: number) => (0.6 * Math.sin((2 * Math.PI * f) / rate + ph) + 0.3 * Math.sin((2 * Math.PI * f) / (rate * 0.47) + ph * 1.7 + 1.3) + 0.15 * Math.sin((2 * Math.PI * f) / (rate * 0.23) + ph * 2.3 + 2.1)) / 1.05;
  const dx = amount * w(0.4) * k, dy = amount * 0.8 * w(2.5) * k, dr = roll * w(4.4) * k;
  const breathe = 0.004 * Math.sin((2 * Math.PI * f) / (rate * 1.6) + 0.9) * k;
  // the scale that keeps a frame translated by `amount` and rolled by `roll` covering the canvas (>= 1.012)
  const r = rad(roll);
  const need = Math.max(1.012, Math.cos(r) + (H / W) * Math.sin(r) + (2 * amount) / W + 0.004);
  const sc = 1 + (need - 1) * k + breathe;
  return <AbsoluteFill style={{transformOrigin: '50% 50%', transform: `translate(${dx.toFixed(2)}px, ${dy.toFixed(2)}px) rotate(${dr.toFixed(3)}deg) scale(${sc.toFixed(4)})`}}>{children}</AbsoluteFill>;
};

// Hook title: the reel's cover title (torn paper tags) on screen from frame 0, so the muted first frame carries the hook
// and matches the profile-grid cover. It slaps in place over frames 0–10 (frame 0 is already the full title), boils on
// threes, then lifts away over 7 frames ending at `outAt`. PapercutVideo holds the taped banner back until `outAt`.
// Configure in episode.json "hook" (build_vo.py copies it into plan.json with `outAt`). Words in `hot` get the yellow tag.
import React from 'react';
import {Easing, interpolate, random, useCurrentFrame} from 'remotion';
import {C, FONT} from '../tokens';
import {GRAIN} from './kit';

export type TornTitleProps = {lines: string[][]; hot?: string[]; size?: number; seed?: string; jitter?: number};

// One torn paper word tag, the same look as the reel covers.
export const TornTag: React.FC<{word: string; hot: boolean; size: number; seed: string; jitter?: number}> = ({word, hot, size, seed, jitter = 0}) => (
  <div style={{
    backgroundColor: hot ? C.sparkYellow : C.tag, backgroundImage: `url(${GRAIN})`, backgroundSize: '420px', backgroundBlendMode: 'multiply',
    color: hot ? C.ink : C.tagText, fontFamily: FONT.caption, fontWeight: 900, fontSize: size, lineHeight: 1, padding: `${size * 0.16}px ${size * 0.26}px ${size * 0.24}px`,
    rotate: `${(random(seed) - 0.5) * 9 + jitter}deg`, translate: `0px ${(random(seed + 'y') - 0.5) * 14}px`,
    filter: 'url(#torn) drop-shadow(3px 8px 9px rgba(0,0,0,0.42))', whiteSpace: 'nowrap',
  }}>{word}</div>
);

// Lines of torn tags, centred.
export const TornTitle: React.FC<TornTitleProps & {step?: number}> = ({lines, hot = [], size = 112, seed = 'cover', step}) => (
  <div style={{display: 'flex', flexDirection: 'column', alignItems: 'center', gap: size * 0.2}}>
    {lines.map((ln, i) => (
      <div key={i} style={{display: 'flex', gap: size * 0.14, justifyContent: 'center'}}>
        {ln.map((w, j) => {
          const s = `${seed}-${i}-${j}-${w}`;
          return <TornTag key={j} word={w} hot={hot.includes(w)} size={size} seed={s} jitter={step === undefined ? 0 : (random(`${s}-${step}`) - 0.5) * 1.4} />;
        })}
      </div>
    ))}
  </div>
);

export type HookTitleProps = {lines: string[][]; hot?: string[]; outAt: number; top?: number; size?: number};

export const HookTitle: React.FC<HookTitleProps> = ({lines, hot = [], outAt, top = 220, size = 108}) => {
  const f = useCurrentFrame();
  const slap = f < 10 ? Math.sin(f * 1.7) * (1 - f / 10) * 0.045 : 0;
  const out = interpolate(f, [Math.max(1, outAt - 7), Math.max(2, outAt)], [0, 1], {extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: Easing.in(Easing.back(1.6))});
  return (
    <div style={{position: 'absolute', top, left: 30, right: 30, transformOrigin: '50% 40%', scale: String(1 + slap),
      translate: `0px ${-out * 640}px`, rotate: `${out * -4}deg`, opacity: 1 - out * 0.4}}>
      <TornTitle lines={lines} hot={hot} size={size} seed="cover" step={Math.floor(f / 3)} />
    </div>
  );
};

// Papercut kit: every prop is paper (grain + rough cut edge + drop shadow), shading is stacked
// cut pieces, motion is transforms driven by useCurrentFrame(). No CSS animations.
import React from 'react';
import {
  AbsoluteFill, Easing, Img, interpolate, random, spring, staticFile, useCurrentFrame, useVideoConfig,
} from 'remotion';
import {C, FONT} from '../tokens';

const clamp = {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'} as const;
export const GRAIN = staticFile('images/papercut/bg/grain.png');

// ---------- filters, mounted once at the root ----------
export const PaperDefs: React.FC = () => (
  <svg width={0} height={0} style={{position: 'absolute'}}>
    <defs>
      <filter id="rough" x="-4%" y="-4%" width="108%" height="108%">
        <feTurbulence type="fractalNoise" baseFrequency="0.035" numOctaves={2} seed={7} result="n" />
        <feDisplacementMap in="SourceGraphic" in2="n" scale={3} xChannelSelector="R" yChannelSelector="G" />
      </filter>
      <filter id="torn" x="-6%" y="-10%" width="112%" height="120%">
        <feTurbulence type="fractalNoise" baseFrequency="0.11" numOctaves={3} seed={11} result="n" />
        <feDisplacementMap in="SourceGraphic" in2="n" scale={7} xChannelSelector="R" yChannelSelector="G" />
      </filter>
    </defs>
  </svg>
);

// Paper wrapper for a whole prop: rough edge + drop shadow (light from the top-left).
export const Paper: React.FC<{children: React.ReactNode; lift?: number; torn?: boolean; style?: React.CSSProperties}> = ({children, lift = 4, torn, style}) => (
  <div style={{position: 'absolute', inset: 0, filter: `url(#${torn ? 'torn' : 'rough'}) drop-shadow(${lift * 0.5}px ${lift}px ${lift * 2}px rgba(0,0,0,0.38))`, ...style}}>
    {children}
  </div>
);

// One cut piece of paper. (x, y) is the top-left corner. `shade` adds a darker underside strip, `hi` a lighter top strip.
export const Slab: React.FC<{
  x: number; y: number; w: number; h: number; color: string; r?: number | string;
  shade?: string; shadeH?: number; hi?: string; hiH?: number; rot?: number; grain?: number;
  children?: React.ReactNode; style?: React.CSSProperties;
}> = ({x, y, w, h, color, r = 4, shade, shadeH = 0.18, hi, hiH = 0.12, rot = 0, grain = 0.55, children, style}) => (
  <div style={{
    position: 'absolute', left: x, top: y, width: w, height: h, borderRadius: r, overflow: 'hidden', rotate: `${rot}deg`,
    backgroundColor: color, backgroundImage: `url(${GRAIN})`, backgroundSize: '520px', backgroundBlendMode: 'multiply',
    boxShadow: 'inset 1.5px 1.5px 0 rgba(255,255,255,0.22)', ...style,
  }}>
    {hi ? <div style={{position: 'absolute', left: 0, top: 0, width: '100%', height: `${hiH * 100}%`, background: hi}} /> : null}
    {shade ? <div style={{position: 'absolute', left: 0, bottom: 0, width: '100%', height: `${shadeH * 100}%`, background: shade}} /> : null}
    {children}
  </div>
);

// Paper disc (circle). (x, y) is the center.
export const Disc: React.FC<{x: number; y: number; d: number; color: string; shade?: string; children?: React.ReactNode; style?: React.CSSProperties}> = ({x, y, d, color, shade, children, style}) => (
  <Slab x={x - d / 2} y={y - d / 2} w={d} h={d} r="50%" color={color} shade={shade} shadeH={0.28} style={style}>{children}</Slab>
);

// Pill label: bold sans caps. (x, y) is the center (unless center={false}).
export const Pill: React.FC<{x: number; y: number; text: string; bg?: string; color?: string; size?: number; rot?: number; center?: boolean}> = ({x, y, text, bg = C.ink, color = '#F3EEE6', size = 30, rot = 0, center = true}) => (
  <div style={{
    position: 'absolute', left: x, top: y, translate: center ? '-50% -50%' : undefined, rotate: `${rot}deg`, whiteSpace: 'nowrap',
    background: bg, color, fontFamily: FONT.label, fontWeight: 800, fontSize: size, letterSpacing: '0.02em',
    padding: `${size * 0.22}px ${size * 0.5}px ${size * 0.26}px`, borderRadius: size * 0.28,
    backgroundImage: `url(${GRAIN})`, backgroundSize: '400px', backgroundBlendMode: 'multiply',
    boxShadow: 'inset 1px 1px 0 rgba(255,255,255,0.18), 1px 3px 5px rgba(0,0,0,0.35)',
  }}>{text}</div>
);

// Cream paper card with grey "text" bars. (x, y) is the top-left corner, like Slab.
export const Card: React.FC<{x: number; y: number; w: number; h: number; lines?: number; rot?: number; color?: string; children?: React.ReactNode; seed?: string}> = ({x, y, w, h, lines = 3, rot = 0, color = C.cream, children, seed = 'card'}) => (
  <Slab x={x} y={y} w={w} h={h} color={color} r={3} rot={rot} shade={C.creamLo} shadeH={0.06}>
    {Array.from({length: lines}).map((_, i) => (
      <div key={i} style={{position: 'absolute', left: w * 0.1, top: h * 0.2 + i * Math.min(26, (h * 0.66) / Math.max(1, lines)), height: 9, width: w * (0.55 + random(`${seed}${i}`) * 0.3), borderRadius: 4, background: '#9B9184'}} />
    ))}
    {children}
  </Slab>
);

// ---------- motion ----------
export const PopIn: React.FC<{at: number; seed?: string; children: React.ReactNode; origin?: string; style?: React.CSSProperties}> = ({at, seed = 'pop', children, origin = '50% 50%', style}) => {
  const frame = useCurrentFrame();
  const {fps} = useVideoConfig();
  const s = spring({frame: frame - at, fps, config: {damping: 12, stiffness: 180, mass: 0.6}});
  const tilt = (random(seed) - 0.5) * 8;
  return (
    <div style={{position: 'absolute', inset: 0, transformOrigin: origin, scale: String(s), rotate: `${tilt * (1 - s)}deg`, opacity: frame < at ? 0 : 1, ...style}}>
      {children}
    </div>
  );
};

export const SlideIn: React.FC<{at: number; dx?: number; dy?: number; dur?: number; children: React.ReactNode}> = ({at, dx = 0, dy = 0, dur = 10, children}) => {
  const frame = useCurrentFrame();
  const u = interpolate(frame, [at, at + dur], [1, 0], {...clamp, easing: Easing.bezier(0.16, 1.25, 0.3, 1)});
  return <div style={{position: 'absolute', inset: 0, translate: `${dx * u}px ${dy * u}px`, opacity: frame < at ? 0 : 1}}>{children}</div>;
};

// Stop-motion boil for screen-space paper overlays: hold 2 frames, then jump.
export const Boil: React.FC<{amp?: number; rot?: number; seed?: string; children: React.ReactNode}> = ({amp = 1.5, rot = 0.2, seed = 'boil', children}) => {
  const step = Math.floor(useCurrentFrame() / 2);
  return (
    <div style={{position: 'absolute', inset: 0, translate: `${(random(`${seed}x${step}`) - 0.5) * 2 * amp}px ${(random(`${seed}y${step}`) - 0.5) * 2 * amp}px`, rotate: `${(random(`${seed}r${step}`) - 0.5) * 2 * rot}deg`}}>
      {children}
    </div>
  );
};

// Scene camera: smooth push toward a focal point, plus an optional accent push at `accent`.
export const CameraPush: React.FC<{dur: number; to?: number; origin?: string; drift?: [number, number]; accent?: number; children: React.ReactNode}> = ({dur, to = 1.07, origin = '50% 45%', drift = [0, 0], accent, children}) => {
  const f = useCurrentFrame();
  const base = interpolate(f, [0, dur], [1, to], {...clamp, easing: Easing.inOut(Easing.quad)});
  const acc = accent === undefined ? 0 : interpolate(f, [accent, accent + 30], [0, 0.1], {...clamp, easing: Easing.bezier(0.2, 0.9, 0.3, 1)});
  const p = interpolate(f, [0, dur], [0, 1], clamp);
  return (
    <AbsoluteFill style={{transformOrigin: origin, scale: String(base + acc), translate: `${drift[0] * p}px ${drift[1] * p}px`}}>
      {children}
    </AbsoluteFill>
  );
};

export const Bg: React.FC<{src: string; tint?: string}> = ({src, tint}) => (
  <AbsoluteFill>
    <Img src={staticFile(src)} style={{width: '100%', height: '100%', objectFit: 'cover'}} />
    {tint ? <AbsoluteFill style={{background: tint, mixBlendMode: 'multiply'}} /> : null}
  </AbsoluteFill>
);

export const Blink: React.FC<{on: React.ReactNode; off: React.ReactNode; hz?: number; from?: number}> = ({on, off, hz = 4, from = 0}) => {
  const f = useCurrentFrame();
  const {fps} = useVideoConfig();
  return <>{f >= from && Math.floor(((f - from) / fps) * hz * 2) % 2 === 0 ? on : off}</>;
};

const STAR = 'M0-10 L2-2 L10 0 L2 2 L0 10 L-2 2 L-10 0 L-2-2Z';
export const SparkleBurst: React.FC<{at: number; x: number; y: number; seed?: string; spread?: number}> = ({at, x, y, seed = 'sp', spread = 1}) => {
  const f = useCurrentFrame() - at;
  if (f < 0 || f > 12) return null;
  const cols = [C.sparkYellow, C.sparkPink, '#FFFFFF'];
  return (
    <>
      {Array.from({length: 6}).map((_, i) => {
        const a = (i / 6) * Math.PI * 2 + random(seed + i);
        const d = (34 + 34 * (f / 12)) * spread;
        return (
          <svg key={i} width={34} height={34} viewBox="-10 -10 20 20" style={{position: 'absolute', left: x + Math.cos(a) * d - 17, top: y + Math.sin(a) * d - 17, scale: String(Math.sin((f / 12) * Math.PI)), rotate: `${f * 15}deg`}}>
            <path d={STAR} fill={cols[i % 3]} />
          </svg>
        );
      })}
    </>
  );
};

export const RadioWaves: React.FC<{x: number; y: number; dir?: number; color?: string; from?: number}> = ({x, y, dir = 0, color = C.amber, from = 0}) => {
  const f = useCurrentFrame() - from;
  if (f < 0) return null;
  return (
    <svg style={{position: 'absolute', left: x - 70, top: y - 70, rotate: `${dir}deg`}} width={140} height={140} viewBox="-70 -70 140 140">
      {[0, 1, 2].map((i) => {
        const p = ((f + i * 5) % 15) / 15;
        const r = 14 + p * 46;
        return <path key={i} d={`M ${r * Math.cos(-0.7)} ${r * Math.sin(-0.7)} A ${r} ${r} 0 0 1 ${r * Math.cos(0.7)} ${r * Math.sin(0.7)}`} stroke={color} strokeWidth={7} strokeLinecap="round" fill="none" opacity={1 - p} />;
      })}
    </svg>
  );
};

export const Typewriter: React.FC<{text: string; at: number; fpc?: number; caret?: boolean}> = ({text, at, fpc = 2, caret = true}) => {
  const f = useCurrentFrame() - at;
  const n = Math.max(0, Math.min(text.length, Math.floor(f / fpc)));
  return (
    <span>
      {text.slice(0, n)}
      {caret && n < text.length && f >= 0 ? <span style={{opacity: Math.floor(f / 8) % 2 ? 0 : 1}}>▌</span> : null}
    </span>
  );
};

// Hand-drawn red annotation ellipse, drawn on over ~8 frames.
export const DrawOnEllipse: React.FC<{at: number; x: number; y: number; w: number; h: number; color?: string; stroke?: number; dur?: number}> = ({at, x, y, w, h, color = C.nogo, stroke = 7, dur = 8}) => {
  const f = useCurrentFrame();
  const p = interpolate(f, [at, at + dur], [0, 1], {...clamp, easing: Easing.out(Easing.quad)});
  if (p <= 0) return null;
  const L = Math.PI * (w + h) * 0.55 * 1.08;
  return (
    <svg style={{position: 'absolute', left: x - w / 2 - 12, top: y - h / 2 - 12}} width={w + 24} height={h + 24}>
      <path d={`M ${w * 0.62 + 12} ${14} C ${w + 30} ${10}, ${w + 22} ${h + 10}, ${w / 2 + 12} ${h + 10} C ${-8} ${h + 12}, ${2} ${8}, ${w * 0.72 + 12} ${18}`} stroke={color} strokeWidth={stroke} fill="none" strokeLinecap="round" strokeDasharray={L} strokeDashoffset={L * (1 - p)} />
    </svg>
  );
};

// Rubber-stamp mark: ink rectangle with a rough double border, lands with a thump.
export const StampMark: React.FC<{at: number; x: number; y: number; text: string; color?: string; size?: number; rot?: number}> = ({at, x, y, text, color = C.nogo, size = 64, rot = -12}) => {
  const f = useCurrentFrame();
  if (f < at) return null;
  const s = interpolate(f, [at, at + 5], [1.5, 1], {...clamp, easing: Easing.out(Easing.back(2))});
  return (
    <div style={{position: 'absolute', left: x, top: y, translate: '-50% -50%', rotate: `${rot}deg`, scale: String(s), filter: 'url(#torn)', opacity: 0.92}}>
      <div style={{border: `${size * 0.09}px solid ${color}`, borderRadius: size * 0.16, padding: `${size * 0.06}px`, }}>
        <div style={{border: `${size * 0.04}px solid ${color}`, borderRadius: size * 0.1, padding: `${size * 0.08}px ${size * 0.3}px`, color, fontFamily: FONT.banner, fontSize: size, lineHeight: 1, whiteSpace: 'nowrap', letterSpacing: '0.03em'}}>{text}</div>
      </div>
    </div>
  );
};

export const GrainOverlay: React.FC = () => {
  const f = useCurrentFrame();
  return (
    <AbsoluteFill style={{pointerEvents: 'none', opacity: 0.07, mixBlendMode: 'multiply'}}>
      <Img src={GRAIN} style={{width: '140%', height: '140%', objectFit: 'cover', translate: `${(random(`g${Math.floor(f / 2)}`) - 0.5) * 60}px ${(random(`h${Math.floor(f / 2)}`) - 0.5) * 60}px`}} />
    </AbsoluteFill>
  );
};

// Idle helpers
export const bob = (f: number, period = 36, amp = 3, phase = 0) => Math.sin(((f + phase) / period) * Math.PI * 2) * amp;
export const hop = (f: number, at: number, dur = 12, h = 14) => { const u = (f - at) / dur; return u > 0 && u < 1 ? Math.sin(u * Math.PI) * h : 0; };
export const reach = (f: number, at: number, back?: number) => {
  const out = interpolate(f, [at, at + 6], [0, 1], {...clamp, easing: Easing.out(Easing.back(1.6))});
  return back === undefined ? out : out * interpolate(f, [back, back + 5], [1, 0], clamp);
};

// Film-look layers for papercut reels: gate weave and exposure flicker (FilmWeave), moving felt fibre (FeltFibre), lens dirt, lamp flicker,
// print halftone and graph paper. Overlays use the textures in public/bg/textures/ (synced by sync_kit.sh). Keep every one of them subtle.
// Overlays sit above the set and below the banner and captions; FilmWeave wraps the set.
import React from 'react';
import {AbsoluteFill, Img, Loop, OffthreadVideo, interpolate, random, staticFile, useCurrentFrame} from 'remotion';
import {Paper} from './kit';

const clamp = {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'} as const;
const TEX = (name: string) => staticFile(`images/papercut/bg/textures/${name}`);
type Blend = 'screen' | 'overlay' | 'multiply' | 'soft-light' | 'color-dodge' | 'normal';

// ---------- FilmWeave ----------

// Film gate weave plus exposure flicker, for a photographed, stop-motion feel: the frame drifts about 1.5 px with a hair of rotation, stepped on twos, and brightness wobbles 2.5% (seeded). `amp` / `flicker` scale each (1 = default).
export const FilmWeave: React.FC<{amp?: number; flicker?: number; seed?: string; children: React.ReactNode}> = ({amp = 1, flicker = 1, seed = 'weave', children}) => {
  const f = useCurrentFrame();
  const step = Math.floor(f / 2);
  const r = (k: string) => random(`${seed}${k}${step}`) * 2 - 1;
  // a slow drift under a small stepped jitter
  const dx = (Math.sin(f / 37) * 0.9 + r('x') * 0.8) * amp, dy = (Math.cos(f / 29) * 0.8 + r('y') * 0.7) * amp, rot = (Math.sin(f / 53) * 0.05 + r('r') * 0.045) * amp;
  const exposure = 1 + flicker * (r('e') * 0.02 + Math.sin(f / 6.5) * 0.008);
  const over = 1 + 0.012 * Math.max(1, amp);   // overscan so the drifting edge never shows
  return (
    <AbsoluteFill style={{transform: `translate(${dx.toFixed(2)}px, ${dy.toFixed(2)}px) rotate(${rot.toFixed(3)}deg) scale(${over})`, filter: `brightness(${exposure.toFixed(4)})`}}>
      {children}
    </AbsoluteFill>
  );
};

// ---------- FeltFibre ----------

// Moving felt-fibre overlay (felt-fibre.mp4, 12 fps on purpose, looped), a living alternative to GrainOverlay. The grey base is crushed to black so only the bright fibres show, then screened on at `opacity` 0.3.
export const FeltFibre: React.FC<{opacity?: number; blend?: Blend}> = ({opacity = 0.3, blend = 'screen'}) => (
  <AbsoluteFill style={{pointerEvents: 'none', mixBlendMode: blend, opacity}}>
    <Loop durationInFrames={155}>
      <OffthreadVideo src={TEX('felt-fibre.mp4')} muted style={{width: '100%', height: '100%', objectFit: 'cover', filter: 'contrast(3.2) brightness(0.9)'}} />
    </Loop>
  </AbsoluteFill>
);

// ---------- LensDirt ----------

// Lens dirt (smudges, dust) for lit dioramas and FocusHunt moments: screened on, so it lifts the darks; (x, y, r) confines it to a lamp or flash. `at` = fade-in frame. Subtle at best; color-dodge hits only highlights but washes cream paper.
export const LensDirt: React.FC<{opacity?: number; at?: number; x?: number; y?: number; r?: number; blend?: Blend}> = ({opacity = 0.35, at = 0, x, y, r = 560, blend = 'screen'}) => {
  const f = useCurrentFrame();
  const k = interpolate(f, [at, at + 10], [0, 1], clamp);
  const mask = x !== undefined && y !== undefined ? `radial-gradient(circle at ${x}px ${y}px, #000 0px, rgba(0,0,0,0.5) ${r * 0.5}px, transparent ${r}px)` : undefined;
  if (k <= 0) return null;
  return (
    <AbsoluteFill style={{pointerEvents: 'none', mixBlendMode: blend, opacity: opacity * k, WebkitMaskImage: mask, maskImage: mask}}>
      <Img src={TEX('lens-dirt.jpg')} style={{width: '100%', height: '100%', objectFit: 'cover'}} />
    </AbsoluteFill>
  );
};

// ---------- LampFlicker ----------

// The brightness multiplier (about 0.3-1.03) of a flickering light at frame f: a gentle shimmer plus an occasional organic dip and recovery. Seeded, so a render never changes. `depth` = how far a dip goes, `every` = frames per chance of one.
export const flickerAt = (f: number, seed = 'lamp', depth = 0.4, every = 42) => {
  let v = 1 + 0.02 * Math.sin(f / 4.3 + random(`${seed}ph`) * 6) + 0.012 * Math.sin(f / 1.7);
  const slot = Math.floor(f / every);
  for (let s = slot - 1; s <= slot; s++) {
    if (random(`${seed}p${s}`) > 0.6) continue;
    const u = f - (s * every + random(`${seed}t${s}`) * (every - 12));
    if (u >= 0 && u < 16) v -= depth * (u < 2 ? u / 2 : Math.exp(-(u - 2) / 4.5)) * (0.8 + 0.2 * Math.cos(u * 1.7));
  }
  return Math.max(0.3, v);
};

// Wraps a light source's glow (a Glow, a lit lamp shade) so it flickers: occasional organic dips that recover, seeded per lamp. Use `flickerAt` for your own maths. Differ the `seed` between lamps.
export const LampFlicker: React.FC<{seed?: string; depth?: number; every?: number; children: React.ReactNode}> = ({seed = 'lamp', depth = 0.4, every = 42, children}) => {
  const v = flickerAt(useCurrentFrame(), seed, depth, every);
  return <AbsoluteFill style={{opacity: Math.min(1, v), filter: v < 0.99 ? `brightness(${(0.82 + 0.18 * v).toFixed(3)})` : undefined}}>{children}</AbsoluteFill>;
};

// ---------- Halftone ----------

// Print texture for "newspaper", "report" and "leak document" beats: a scanned print grain multiplied over the frame. With children it also washes the colour toward newsprint (`tone` 0-1 desaturation). `opacity` 0.4.
export const Halftone: React.FC<{opacity?: number; tone?: number; at?: number; blend?: Blend; children?: React.ReactNode}> = ({opacity = 0.2, tone = 0.45, at = 0, blend = 'multiply', children}) => {
  const f = useCurrentFrame();
  const k = interpolate(f, [at, at + 6], [0, 1], clamp);
  return (
    <>
      {children ? <AbsoluteFill style={{filter: `grayscale(${(tone * k).toFixed(3)}) sepia(${(0.25 * k).toFixed(3)}) contrast(${1 + 0.08 * k})`}}>{children}</AbsoluteFill> : null}
      <AbsoluteFill style={{pointerEvents: 'none', mixBlendMode: blend, opacity: opacity * k}}>
        <Img src={TEX('halftone-scan.jpg')} style={{width: '100%', height: '100%', objectFit: 'cover'}} />
      </AbsoluteFill>
    </>
  );
};

// ---------- GraphPaper ----------

// Graph paper for plan, sketch and maths beats. With no box it is a full-frame backdrop (`tint` multiplies a colour, `dim` darkens); with (x, y, w, h) it is a paper card surface with the usual rough edge and shadow, tilted by `rot`.
export const GraphPaper: React.FC<{x?: number; y?: number; w?: number; h?: number; rot?: number; tint?: string; dim?: number; children?: React.ReactNode}> = ({x, y, w, h, rot = 0, tint, dim = 0, children}) => {
  const tex = <Img src={TEX('graph-paper.jpg')} style={{position: 'absolute', inset: 0, width: '100%', height: '100%', objectFit: 'cover'}} />;
  const shade = (
    <>
      {tint ? <AbsoluteFill style={{backgroundColor: tint, mixBlendMode: 'multiply'}} /> : null}
      {dim > 0 ? <AbsoluteFill style={{backgroundColor: '#000', opacity: Math.min(1, dim)}} /> : null}
    </>
  );
  if (x === undefined || y === undefined || !w || !h) return <AbsoluteFill>{tex}{shade}{children}</AbsoluteFill>;
  return (
    <div style={{position: 'absolute', inset: 0, transformOrigin: `${x + w / 2}px ${y + h / 2}px`, rotate: `${rot}deg`}}>
      <Paper lift={8}>
        <div style={{position: 'absolute', left: x, top: y, width: w, height: h, overflow: 'hidden', borderRadius: 4, boxShadow: 'inset 1.5px 1.5px 0 rgba(255,255,255,0.22)'}}>
          <div style={{position: 'absolute', left: 0, top: 0, width: w, height: h}}>{tex}{shade}</div>
        </div>
      </Paper>
      {children}
    </div>
  );
};

// Small keyframe helpers every hand-animated scene reuses (so scene files do not each carry a copy).
// keyed = piecewise eased value through [frame, value] keys; swing = decaying follow-through; onN = stepped "on twos";
// clamp01 and lcg are the usual 0-1 clamp and a seeded random.
import {Easing} from 'remotion';

/** Piecewise value through [frame, value] keys with an ease on each segment. */
export const keyed = (f: number, keys: [number, number][], ease: (t: number) => number = Easing.out(Easing.cubic)) => {
  if (f <= keys[0][0]) return keys[0][1];
  for (let i = 1; i < keys.length; i++) {
    if (f <= keys[i][0]) {
      const [a, va] = keys[i - 1], [b, vb] = keys[i];
      return va + (vb - va) * ease((f - a) / Math.max(1, b - a));
    }
  }
  return keys[keys.length - 1][1];
};
/** A decaying swing that starts at frame `at` (pendulum follow-through: 2 cycles, then still). */
export const swing = (f: number, at: number, amp: number, tau = 9, period = 14) =>
  f < at ? 0 : amp * Math.exp(-(f - at) / tau) * Math.sin(((f - at) / period) * Math.PI * 2);
/** Hold each value for `n` frames (hand-made, stepped motion). */
export const onN = (f: number, n = 2) => f - (f % n);
/** Clamp to 0-1. */
export const clamp01 = (v: number) => Math.min(1, Math.max(0, v));
/** Seeded random in [0, 1) from a counter. */
export const lcg = (seed: number) => { let s = seed; return () => { s = (s * 1664525 + 1013904223) % 4294967296; return s / 4294967296; }; };

// Screen-space overlays: taped headline banner (boils on twos) and word-pop torn caption tags.
import React, {useEffect, useState} from 'react';
import type {Caption} from '@remotion/captions';
import {fitText} from '@remotion/layout-utils';
import {continueRender, delayRender, random, spring, useCurrentFrame, useVideoConfig} from 'remotion';
import {C, FONT} from '../tokens';
import {fontsLoaded, fontsReady} from '../fonts';
import {Boil, GRAIN} from './kit';

export const TapeBanner: React.FC<{text: string; seed: string}> = ({text, seed}) => {
  const frame = useCurrentFrame();
  const {fps} = useVideoConfig();
  const s = spring({frame, fps, config: {damping: 14, stiffness: 220, mass: 0.6}});
  // Measure only once the banner font is loaded in this tab (fonts.ts): measuring early caches the fallback width.
  const [ready, setReady] = useState(fontsLoaded());
  useEffect(() => {
    if (ready) return;
    const h = delayRender('TapeBanner: waiting for fonts');
    fontsReady.then(() => { setReady(true); continueRender(h); });
  }, [ready]);
  const size = ready ? Math.min(62, fitText({text, withinWidth: 820, fontFamily: FONT.banner, fontWeight: '400', textTransform: 'uppercase', validateFontIsLoaded: true}).fontSize) : 62;
  return (
    <Boil seed={`b${seed}`}>
      <div style={{position: 'absolute', top: 1920 * 0.14, left: 1080 * 0.06, width: 1080 * 0.88, rotate: `${-1 + (random(seed) - 0.5) * 0.8}deg`, scale: String(0.94 + 0.06 * s)}}>
        <div style={{
          backgroundColor: C.cream, backgroundImage: `url(${GRAIN})`, backgroundSize: '520px', backgroundBlendMode: 'multiply',
          padding: '30px 36px 32px', textAlign: 'center', fontFamily: FONT.banner, fontSize: size, lineHeight: 1.05, color: C.ink,
          letterSpacing: '-0.01em', textTransform: 'uppercase', whiteSpace: 'nowrap',
          filter: 'url(#torn) drop-shadow(2px 6px 8px rgba(0,0,0,0.38))',
        }}>{text}</div>
        {[{left: -34, rotate: '-35deg'}, {right: -34, rotate: '35deg'}].map((p, i) => (
          <div key={i} style={{position: 'absolute', top: -16, width: 124, height: 46, background: C.tape, opacity: 0.8, filter: 'url(#torn)', ...p}} />
        ))}
      </div>
    </Boil>
  );
};

type Page = {words: Caption[]; startMs: number; endMs: number};
export const pageWords = (caps: Caption[], max = 3): Page[] => {
  const pages: Page[] = [];
  let cur: Caption[] = [];
  caps.forEach((w, i) => {
    cur.push(w);
    const next = caps[i + 1];
    const punct = /[.,!?:;…]$/.test(w.text.trim());
    const gap = next ? next.startMs - w.endMs > 250 : true;
    if (cur.length >= max || punct || gap) {
      pages.push({words: cur, startMs: cur[0].startMs, endMs: next ? next.startMs : w.endMs + 400});
      cur = [];
    }
  });
  return pages;
};

export const WordTagCaptions: React.FC<{captions: Caption[]; bandY: (ms: number) => number}> = ({captions, bandY}) => {
  const frame = useCurrentFrame();
  const {fps} = useVideoConfig();
  const ms = (frame / fps) * 1000;
  const pages = React.useMemo(() => pageWords(captions), [captions]);
  const page = pages.find((p) => ms >= p.startMs - 40 && ms < p.endMs);
  if (!page) return null;
  return (
    <div style={{position: 'absolute', top: 1920 * bandY(page.startMs), left: 60, right: 60, display: 'flex', justifyContent: 'center', flexWrap: 'wrap', gap: 12}}>
      {page.words.filter((w) => ms >= w.startMs - 40).map((w) => {
        const at = Math.round((w.startMs / 1000) * fps) - 1;
        const s = spring({frame: frame - at, fps, config: {damping: 14, stiffness: 260, mass: 0.5}});
        const key = `${w.startMs}-${w.text}`;
        const word = w.text.trim().replace(/[.,:…]+$/, '');
        return (
          <div key={key} style={{
            backgroundColor: C.tag, backgroundImage: `url(${GRAIN})`, backgroundSize: '420px', backgroundBlendMode: 'multiply',
            color: C.tagText, fontFamily: FONT.caption, fontWeight: 900, fontSize: 70, lineHeight: 1, padding: '12px 20px 18px',
            rotate: `${(random(key) - 0.5) * 10}deg`,
            translate: `0px ${(random(key + 'y') - 0.5) * 12 + (1 - s) * -10 + Math.sin((frame + random(key) * 40) / 9) * 1.2}px`,
            scale: String(0.6 + 0.4 * s),
            filter: 'url(#torn) drop-shadow(2px 5px 6px rgba(0,0,0,0.38))',
          }}>{word}</div>
        );
      })}
    </div>
  );
};

// Proof beat: a real browser capture laid on a paper card (RealShot) with hand-drawn red marker strokes over it (MarkerCircle, MarkerUnderline, MarkerArrow).
// Use it once per reel, on the proof beat: it is the one place a real page, real logos and real UI appear. Capture the page with lib/tools/capture.mjs.
// Marker strokes are filled ribbons (varying width, rough ends) revealed by a stroke-dashoffset mask, drawn on from `at` over `dur` frames.
import React, {useId} from 'react';
import {Easing, Img, interpolate, random, staticFile, useCurrentFrame} from 'remotion';
import {C, FONT, H, W} from '../tokens';
import {Boil, GRAIN, Paper, PopIn, Slab} from './kit';
import {TapeCorners} from './tape';

const clamp = {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'} as const;
const MARKER = '#DE3B2D';

// ---------- RealShot ----------

// A real screenshot (public/ PNG from tools/capture.mjs) on a paper card: tape corners, shadow, print grain, pop-in at `at`. `ratio` = image h/w (capture.mjs prints it); `chrome` = URL text for a paper browser bar; children share the tilt.
export const RealShot: React.FC<{src: string; x: number; y: number; w: number; ratio?: number; rot?: number; tape?: boolean; at?: number; chrome?: string; children?: React.ReactNode}> = ({src, x, y, w, ratio = 0.5625, rot = 0, tape = true, at = 0, chrome, children}) => {
  const pad = 16, bar = chrome ? 64 : 0;
  const iw = w - pad * 2, ih = iw * ratio, h = pad + bar + ih + pad + 6;
  const cx = x + w / 2, cy = y + h / 2;
  return (
    <PopIn at={at} seed={`rs${src}`} origin={`${cx}px ${cy}px`}>
      <div style={{position: 'absolute', inset: 0, transformOrigin: `${cx}px ${cy}px`, rotate: `${rot}deg`}}>
        <Paper lift={10}>
          <Slab x={x} y={y} w={w} h={h} color={C.creamHi} shade={C.creamLo} shadeH={0.025} r={6} />
          {chrome ? <Slab x={x + pad} y={y + pad} w={iw} h={bar} color="#D4CBBC" r="8px 8px 0 0" /> : null}
        </Paper>
        {chrome ? (
          <>
            {[0, 1, 2].map((i) => <div key={i} style={{position: 'absolute', left: x + pad + 24 + i * 28, top: y + pad + bar / 2 - 8, width: 16, height: 16, borderRadius: '50%', backgroundColor: ['#C9573C', '#C89B4A', '#7C9A6B'][i], opacity: 0.85}} />)}
            <div style={{position: 'absolute', left: x + pad + 126, top: y + pad + 10, width: iw - 126 - 20, height: bar - 20, borderRadius: 14, backgroundColor: C.creamHi, padding: '0 18px', overflow: 'hidden', boxSizing: 'border-box',
              fontFamily: FONT.mono, fontSize: 24, lineHeight: `${bar - 20}px`, color: C.inkSoft, whiteSpace: 'nowrap', textOverflow: 'ellipsis'}}>{chrome}</div>
          </>
        ) : null}
        <div style={{position: 'absolute', left: x + pad, top: y + pad + bar, width: iw, height: ih, overflow: 'hidden', backgroundColor: '#fff'}}>
          <Img src={staticFile(src)} style={{display: 'block', width: '100%', height: '100%'}} />
          <div style={{position: 'absolute', inset: 0, backgroundImage: `url(${GRAIN})`, backgroundSize: '520px', mixBlendMode: 'multiply', opacity: 0.3}} />
        </div>
        {tape ? <TapeCorners x={x} y={y} w={w} h={h} /> : null}
        {children}
      </div>
    </PopIn>
  );
};

// ---------- marker strokes ----------

type Pt = [number, number];
// smooth seeded wobble in about -1..1
const wob = (seed: string, t: number) => (Math.sin(t * 11 + random(`${seed}a`) * 6.28) * 0.5 + Math.sin(t * 23 + random(`${seed}b`) * 6.28) * 0.3 + Math.sin(t * 41 + random(`${seed}c`) * 6.28) * 0.2);
const taper = (t: number) => Math.min(1, 0.32 + (t / 0.05) * 0.68, 0.4 + ((1 - t) / 0.07) * 0.6);

// A filled ribbon around the centre line `pts`, half-width hw(t), with rough chisel-cut ends.
const ribbon = (pts: Pt[], hw: (t: number) => number, seed: string) => {
  const L: Pt[] = [], R: Pt[] = [];
  pts.forEach((p, i) => {
    const a = pts[Math.max(0, i - 1)], b = pts[Math.min(pts.length - 1, i + 1)];
    const dx = b[0] - a[0], dy = b[1] - a[1], len = Math.hypot(dx, dy) || 1;
    const nx = -dy / len, ny = dx / len, h = hw(i / (pts.length - 1));
    L.push([p[0] + nx * h, p[1] + ny * h]);
    R.push([p[0] - nx * h, p[1] - ny * h]);
  });
  const cap = (i: number, dir: 1 | -1): Pt => {
    const p = pts[i], q = pts[i + dir] ?? pts[i], len = Math.hypot(p[0] - q[0], p[1] - q[1]) || 1;
    const k = hw(i / (pts.length - 1)) * (0.7 + random(`${seed}cap${i}`) * 0.7);
    return [p[0] + ((p[0] - q[0]) / len) * k, p[1] + ((p[1] - q[1]) / len) * k];
  };
  const ring = [...L, cap(pts.length - 1, -1), ...R.reverse(), cap(0, 1)];
  return `M${ring.map((p) => `${p[0].toFixed(1)} ${p[1].toFixed(1)}`).join('L')}Z`;
};

// One marker stroke, revealed to `p` (0-1) along its centre line. `bleed` = felt-tip on paper: a ragged, softly feathered edge, a darker core, and ink pooling where the pen lands and lifts.
const Stroke: React.FC<{pts: Pt[]; width: number; p: number; color: string; seed: string; bleed?: boolean}> = ({pts, width, p, color, seed, bleed = false}) => {
  const id = useId().replace(/:/g, '');
  if (p <= 0.001) return null;
  const hw = (t: number) => (width / 2) * (0.8 + 0.2 * wob(seed + 'w', t)) * taper(t);
  const centre = `M${pts.map((q) => `${q[0].toFixed(1)} ${q[1].toFixed(1)}`).join('L')}`;
  const xs = pts.map((q) => q[0]), ys = pts.map((q) => q[1]), pad = width * 2 + 20;
  const box = {x: Math.min(...xs) - pad, y: Math.min(...ys) - pad, width: Math.max(...xs) - Math.min(...xs) + pad * 2, height: Math.max(...ys) - Math.min(...ys) + pad * 2};
  const rr = random(`${seed}f`) * 40 | 0;
  const pool = Math.min(1, Math.max(0, (p - 0.96) / 0.04));   // the pen lifts: ink gathers at the end
  return (
    <svg width={W} height={H} viewBox={`0 0 ${W} ${H}`} style={{position: 'absolute', left: 0, top: 0, overflow: 'visible'}}>
      <defs>
        <mask id={`k${id}`} maskUnits="userSpaceOnUse" x={-W} y={-H} width={W * 3} height={H * 3}>
          <path d={centre} pathLength={1} fill="none" stroke="#fff" strokeWidth={width * 2.3} strokeLinecap="round" strokeLinejoin="round" strokeDasharray="1 2" strokeDashoffset={1 - Math.min(1, p)} />
        </mask>
        <filter id={`b${id}`} filterUnits="userSpaceOnUse" {...box}>
          <feTurbulence type="fractalNoise" baseFrequency="0.5" numOctaves={3} seed={rr} result="n" />
          <feDisplacementMap in="SourceGraphic" in2="n" scale={width * 0.55} xChannelSelector="R" yChannelSelector="G" result="d" />
          <feGaussianBlur in="d" stdDeviation={0.7} />
        </filter>
      </defs>
      {bleed ? (
        <g filter={`url(#b${id})`} style={{mixBlendMode: 'multiply'}} opacity={0.93}>
          <path d={ribbon(pts, hw, seed)} fill={color} mask={`url(#k${id})`} />
          <path d={ribbon(pts, (t) => hw(t) * 0.5, `${seed}c`)} fill="#8A1A12" opacity={0.3} mask={`url(#k${id})`} />
          <circle cx={pts[0][0]} cy={pts[0][1]} r={hw(0.04) * 1.5} fill="#8A1A12" opacity={0.5} />
          <circle cx={pts[pts.length - 1][0]} cy={pts[pts.length - 1][1]} r={hw(0.97) * 1.6} fill="#8A1A12" opacity={0.55 * pool} />
        </g>
      ) : (
        <path d={ribbon(pts, hw, seed)} fill={color} opacity={0.93} mask={`url(#k${id})`} filter="url(#rough)" style={{mixBlendMode: 'multiply'}} />
      )}
    </svg>
  );
};

// Draw-on progress for a stroke: a quick hand stroke, slightly eased at both ends.
const useDraw = (at: number, dur: number) => {
  const f = useCurrentFrame();
  return interpolate(f, [at, at + Math.max(1, dur)], [0, 1], {...clamp, easing: Easing.bezier(0.35, 0, 0.5, 1)});
};

// Hand-drawn red marker ellipse around the centre (x, y), w x h, drawn on over `dur` frames from `at` (default 10). Overshoots its start (`loops` 1.15). `bleed` (on) = felt-tip ink: ragged edge, pooling at start and end. `width` = pen px.
export const MarkerCircle: React.FC<{x: number; y: number; w: number; h: number; at: number; dur?: number; color?: string; loops?: number; seed?: string; width?: number; bleed?: boolean}> = ({x, y, w, h, at, dur = 10, color = MARKER, loops = 1.15, seed = 'mc', width = 13, bleed = true}) => {
  const p = useDraw(at, dur);
  const N = Math.ceil(80 * loops), th0 = -2.5 + (random(`${seed}s`) - 0.5) * 0.7, spiral = width * 3.3;
  const pts: Pt[] = Array.from({length: N + 1}, (_, i) => {
    const t = i / N, th = th0 + t * loops * Math.PI * 2, grow = -spiral / 2 + t * spiral;
    const rx = w / 2 + grow + wob(`${seed}x`, t) * w * 0.018, ry = h / 2 + grow + wob(`${seed}y`, t) * h * 0.03;
    return [x + rx * Math.cos(th) + wob(`${seed}cx`, t) * 3, y + ry * Math.sin(th) + wob(`${seed}cy`, t) * 3];
  });
  return <Boil amp={0.9} rot={0.12} seed={seed}><Stroke pts={pts} width={width} p={p} color={color} seed={seed} bleed={bleed} /></Boil>;
};

// Hand-drawn red marker underline from (x, y) across `w` px, left to right, with a slight slope and wobble; `double` adds a second pass back underneath.
export const MarkerUnderline: React.FC<{x: number; y: number; w: number; at: number; dur?: number; color?: string; double?: boolean; seed?: string; width?: number; bleed?: boolean}> = ({x, y, w, at, dur = 9, color = MARKER, double = false, seed = 'mu', width = 11, bleed = true}) => {
  const p = useDraw(at, dur * (double ? 1.8 : 1));
  const slope = (random(`${seed}sl`) - 0.5) * 14;
  const line = (yy: number, dir: 1 | -1, sd: string): Pt[] => Array.from({length: 40}, (_, i) => {
    const t = i / 39, u = dir === 1 ? t : 1 - t;
    return [x + w * u, yy + slope * u + wob(sd, t) * 3.2];
  });
  const p1 = double ? Math.min(1, p / 0.55) : p, p2 = Math.max(0, (p - 0.55) / 0.45);
  return (
    <Boil amp={0.9} rot={0.1} seed={seed}>
      <Stroke pts={line(y, 1, `${seed}1`)} width={width} p={p1} color={color} seed={`${seed}1`} bleed={bleed} />
      {double ? <Stroke pts={line(y + width * 1.9, -1, `${seed}2`)} width={width * 0.9} p={p2} color={color} seed={`${seed}2`} bleed={bleed} /> : null}
    </Boil>
  );
};

// Hand-drawn red marker arrow from (x, y) to the tip (tx, ty): a slightly bowed shaft, then two barbs. `bend` = how much the shaft bows (0.14 of its length).
export const MarkerArrow: React.FC<{x: number; y: number; tx: number; ty: number; at: number; dur?: number; color?: string; bend?: number; seed?: string; width?: number; bleed?: boolean}> = ({x, y, tx, ty, at, dur = 12, color = MARKER, bend = 0.14, seed = 'ma', width = 13, bleed = true}) => {
  const p = useDraw(at, dur);
  const dx = tx - x, dy = ty - y, len = Math.hypot(dx, dy), nx = -dy / len, ny = dx / len;
  const cx = (x + tx) / 2 + nx * len * bend, cy = (y + ty) / 2 + ny * len * bend;
  const shaft: Pt[] = Array.from({length: 36}, (_, i) => {
    const t = i / 35, a = (1 - t) * (1 - t), b = 2 * (1 - t) * t, c = t * t;
    return [a * x + b * cx + c * tx + wob(`${seed}s`, t) * 2.5, a * y + b * cy + c * ty + wob(`${seed}t`, t) * 2.5];
  });
  const tdx = tx - cx, tdy = ty - cy, tl = Math.hypot(tdx, tdy) || 1, ang = Math.atan2(tdy, tdx), bl = Math.min(64, len * 0.3);
  const barb = (da: number, k: string): Pt[] => Array.from({length: 12}, (_, i) => {
    const t = i / 11, a = ang + Math.PI + da;
    return [tx + Math.cos(a) * bl * t + wob(`${seed}${k}`, t) * 1.5, ty + Math.sin(a) * bl * t + wob(`${seed}${k}y`, t) * 1.5];
  });
  void tl;
  const ps = Math.min(1, p / 0.7), pb1 = Math.max(0, Math.min(1, (p - 0.7) / 0.15)), pb2 = Math.max(0, Math.min(1, (p - 0.85) / 0.15));
  return (
    <Boil amp={0.9} rot={0.1} seed={seed}>
      <Stroke pts={shaft} width={width} p={ps} color={color} seed={`${seed}a`} bleed={bleed} />
      <Stroke pts={barb(0.5, 'b1')} width={width * 0.92} p={pb1} color={color} seed={`${seed}b`} bleed={bleed} />
      <Stroke pts={barb(-0.5, 'b2')} width={width * 0.92} p={pb2} color={color} seed={`${seed}c`} bleed={bleed} />
    </Boil>
  );
};

