    const h = (L.hMin + rnd(L.seed + 'h' + i) * (L.hMax - L.hMin)) * (1 - (1 - L.topK) * upness);
    return {x: p[0] - n[0] * w * 0.5, y: p[1] - n[1] * w * 0.5, w, h, ang: Math.max(-10, Math.min(10, lean * 0.14)), s: rnd(L.seed + 's' + i) > 0.5 ? 1 : -1};
  });
