  );
};
const ROLE_COLOR_NAME: Record<RoleId, string> = {skeptic: 'red', customer: 'green', competitor: 'orange', investor: 'yellow'};

// ---------- verdict card: a cream card with a rubber-stamped verdict ----------
// stampAt: frame the stamp slams down (relative to the scene). (x, y) = top-left.
export const Verdict: React.FC<{x: number; y: number; w?: number; role: RoleId; text: string; stampAt: number; rot?: number}> = ({x, y, w = 300, role, text, stampAt, rot = 0}) => {
  const f = useCurrentFrame();
  const r = ROLE[role];
  const h = w * 0.62;
  const s = interpolate(f, [stampAt - 3, stampAt, stampAt + 3], [1.8, 0.94, 1], clamp);
  return (
    <div style={{position: 'absolute', left: x, top: y, width: w, height: h, rotate: `${rot}deg`}}>
      <Paper lift={5}>
        <Slab x={0} y={0} w={w} h={h} color={C.creamHi} r={6} shade={C.creamLo} shadeH={0.06}>
          <div style={{position: 'absolute', left: 0, right: 0, top: 0, height: h * 0.24, background: r.color}} />
          <div style={{position: 'absolute', left: 14, top: h * 0.035, fontFamily: FONT.label, fontWeight: 800, fontSize: h * 0.15, color: '#fff'}}>{r.tag}</div>
          {[0.36, 0.5].map((t, i) => <div key={i} style={{position: 'absolute', left: w * 0.08, top: h * t, height: 8, width: w * (0.5 + 0.3 * random(`vd${role}${i}`)), borderRadius: 4, background: '#B6AC9C'}} />)}
          {f >= stampAt - 3 ? (
            <div style={{position: 'absolute', left: '50%', top: h * 0.7, translate: '-50% -50%', rotate: '-8deg', scale: String(s), whiteSpace: 'nowrap',
              border: `5px solid ${C.nogo}`, borderRadius: 8, padding: '2px 12px', fontFamily: FONT.banner, fontSize: h * 0.17, color: C.nogo, opacity: 0.9}}>{text}</div>
          ) : null}
        </Slab>
      </Paper>
    </div>
  );
};

// ---------- campfire + skewer ----------
// (x, y) = ground centre of the fire. Flames flicker on twos (stepped, like replacement cels).
export const Campfire: React.FC<{x: number; y: number; s?: number; on?: number}> = ({x, y, s = 1, on = 1}) => {
  const f = useCurrentFrame();
  const step = Math.floor(f / 2);
  const flame = (k: number, col: string, w: number, h: number, dx: number) => {
    const j = (random(`fl${k}${step}`) - 0.5) * 0.18;
    return <Slab key={k + col} x={dx * s - (w * s) / 2} y={-h * s * (1 + j) * on} w={w * s} h={h * s * (1 + j) * on} color={col} r="50% 50% 30% 30% / 70% 70% 30% 30%" rot={j * 30} />;
  };
  return (
    <div style={{position: 'absolute', left: x, top: y, width: 0, height: 0}}>
      <div style={{position: 'absolute', left: -220 * s, top: -330 * s, width: 440 * s, height: 400 * s, borderRadius: '50%', opacity: 0.4 * on,
        background: 'radial-gradient(circle, rgba(255,170,70,0.9) 0%, rgba(255,140,50,0.25) 45%, rgba(255,140,50,0) 70%)'}} />
      <Paper lift={5}>
        {on > 0 ? <>{flame(1, '#E2562F', 150, 210, -10)}{flame(2, '#F08A2E', 110, 160, 14)}{flame(3, '#F6C64C', 64, 96, 0)}</> : null}
        <Slab x={-140 * s} y={-34 * s} w={280 * s} h={44 * s} color={C.woodHi} shade={C.woodLo} shadeH={0.4} r={20} rot={-12} />
        <Slab x={-140 * s} y={-34 * s} w={280 * s} h={44 * s} color={C.wood} shade={C.woodLo} shadeH={0.4} r={20} rot={12} />
        {[-150, -80, 0, 80, 150].map((dx, i) => <Disc key={i} x={dx * s} y={8 * s} d={(46 + (i % 2) * 14) * s} color="#8D877C" shade="#6F6A61" />)}
      </Paper>
    </div>
  );
};

// A long roasting fork; (x, y) = handle end, len in px, angle in degrees (0 = pointing right, negative = up).
export const Skewer: React.FC<{x: number; y: number; len?: number; angle?: number; children?: React.ReactNode}> = ({x, y, len = 420, angle = -20, children}) => (
  <div style={{position: 'absolute', left: x, top: y, width: 0, height: 0, rotate: `${angle}deg`}}>
    <Paper lift={4}>
      <Slab x={0} y={-9} w={110} h={18} color={C.wood} shade={C.woodLo} shadeH={0.4} r={8} />
      <Slab x={108} y={-4} w={len - 108} h={8} color={C.metal} shade={C.metalLo} shadeH={0.5} r={3} />
    </Paper>
    {children ? <div style={{position: 'absolute', left: len, top: 0}}>{children}</div> : null}
  </div>
);

// Small stat card with a big number (numbers are physical props). (x, y) = top-left.
// tape: two tape strips across the top corners so a wall-hung card is never loose.
export const NumberCard: React.FC<{x: number; y: number; w: number; h: number; big: string; small?: string; color?: string; ink?: string; rot?: number; tape?: boolean}> =
  ({x, y, w, h, big, small, color = C.creamHi, ink = C.ink, rot = 0, tape = false}) => (
    <div style={{position: 'absolute', left: x, top: y, width: w, height: h, rotate: `${rot}deg`}}>
      <Paper lift={5}>
        <Slab x={0} y={0} w={w} h={h} color={color} r={10} shade="rgba(0,0,0,0.12)" shadeH={0.07}>
          <div style={{position: 'absolute', left: 0, right: 0, top: small ? '10%' : 0, bottom: small ? '30%' : 0, display: 'grid', placeItems: 'center', fontFamily: FONT.banner, fontSize: h * (small ? 0.46 : 0.6), color: ink, lineHeight: 1}}>{big}</div>
          {small ? <div style={{position: 'absolute', left: 0, right: 0, bottom: '9%', textAlign: 'center', fontFamily: FONT.label, fontWeight: 800, fontSize: h * 0.14, color: ink, opacity: 0.8}}>{small}</div> : null}
        </Slab>
      </Paper>
      {tape ? <TapeCorners x={0} y={0} w={w} h={h} len={Math.max(48, Math.min(80, w * 0.22))} /> : null}
    </div>
  );

export {Pill};

// Where a Critter's arm tip is, so a scene can place a held prop that stays upright (Critter's own holdR rotates
// with the arm). Matches Critter's geometry; ignores `lean`. side 1 = right arm, -1 = left arm.
export const armTip = (o: {x: number; y: number; size?: number; reach: number; angle: number; face?: 1 | -1; lift?: number; f?: number; phase?: number; side?: 1 | -1; idle?: boolean}) => {
  const {x, y, size = 240, reach, angle, face = 1, lift = 0, f = 0, phase = 0, side = 1, idle = true} = o;
  const u = size / 10, bodyW = 10 * u, bodyH = 7 * u, legH = 2.2 * u;
  const b = idle ? bob(f, 36, 3, phase) : 0;
  const len = 2.3 * u + reach * 5 * u;
  const ax = side === 1 ? bodyW / 2 - 0.4 * u : -bodyW / 2 + 0.4 * u;
  const ay = -legH - bodyH + 3.4 * u - lift + b;
  const a = ((side === 1 ? angle : 180 - angle) * Math.PI) / 180;
  const tx = ax + Math.cos(a) * len, ty = ay + Math.sin(a) * len;
  return {x: x + face * tx, y: y + ty};
};

// A stadium of tiny sleepers, drawn cheaply: ~1100 people in 25 tiers (one SVG per tier, instanced <use>) so a full-frame crowd renders fast,
// with a few "hero" real <Critter>s seated in the rows who can lift, speak up and wake. Pan the stand sideways with `pan`; back tiers drift less.
//   Crowd         the stand: tiers, seat boards, floating z tags, and every hero that is still asleep or seated
//   AwakeHeroes   the heroes that are awake, drawn above any dim layer or glow so it never greys them out (render after your overlay)
//   placeHeroes / heroScreenX / CROWD_HEROES   where heroes sit; use them to aim sparkles, labels or arrows at a hero
// Layout (1080x1920 frame, no x/y props: the crowd fills the frame). Tier 0 (front) has 86 px critters on a baseline at y 1440; each tier behind
// is 0.93x the size and sits higher, up to a back row near y 710. Every tier is 1620 px wide from x -270, so `pan` can run -270..270 px (front
// tiers move `pan`, back tiers less) without showing an edge. Hero `x` is the screen x of the hero's feet when the stand is at `heroPan`.
import React from 'react';
import {interpolate, random, useCurrentFrame} from 'remotion';
import {C, FONT} from '../tokens';
import {Paper, Slab, bob} from '../paper/kit';
import {Critter, type Acc, type Expr} from '../cast/Critter';

const CROWD_W = 1620, CROWD_X0 = -270;   // each tier is wider than the screen so the pan never shows an edge
const BODY = ['#C98B5B', '#8FB3A0', '#B9A2CF', '#E0B65C', '#7FA7C9', '#D98C8C', '#A9C27A'];
const BODY_LO = ['#9C6840', '#678A78', '#8B76A8', '#B38A38', '#5A82A5', '#B06666', '#7F9855'];
const HAT = ['#F3A53B', '#F3A53B', '#F3A53B', '#E8E2D2', '#E66F3C', '#F0D24A'];
const HAT_LO = ['#C07F22', '#C07F22', '#C07F22', '#BDB6A2', '#B4502A', '#C4A62C'];

type Tier = {k: number; size: number; B: number; pitch: number; n: number; px: number};
const buildTiers = (): Tier[] => {
  const out: Tier[] = [];
  let size = 86, B = 1440;
  for (let k = 0; k < 25; k++) {
    const pitch = size * 1.06;
    out.push({k, size, B, pitch, n: Math.ceil(CROWD_W / pitch), px: ((k * 0.37) % 1) * pitch});
    B -= 0.72 * size;
    size *= 0.93;
  }
  return out.reverse();   // back tier first = draw order
};
const TIERS = buildTiers();
const tierOf = (k: number) => TIERS.find((t) => t.k === k)!;
const tierShift = (t: Tier, pan: number) => -pan * Math.pow(t.size / 86, 0.8);   // parallax: back tiers drift less

function mixHex(a: string, b: string, t: number) {
  const pa = [1, 3, 5].map((i) => parseInt(a.slice(i, i + 2), 16)), pb = [1, 3, 5].map((i) => parseInt(b.slice(i, i + 2), 16));
  return '#' + pa.map((v, i) => Math.round(v + (pb[i] - v) * t).toString(16).padStart(2, '0')).join('');
}
type Look = {haze: string; dusk: string};
const calm = (c: string, look: Look) => mixHex(c, look.dusk, 0.24);   // mute the bright critters toward the stage's dusk

// ---------- heroes: where they sit ----------

// A hero's seat: front-tier index k (0 = front row, up to about 8 stay big enough to read) and its screen x at `heroPan`.
export type HeroSpot = {k: number; x: number};
// A hero placed on a seat: `slot` is the seat in its tier, `x` the feet position when pan is 0 (add tierShift via heroScreenX for any pan).
export type PlacedHero = {k: number; slot: number; x: number};

// Ten hero seats in front tiers 2-6, clustered mid-screen (the default for Crowd and AwakeHeroes); x is the screen x when heroPan is 130.
export const CROWD_HEROES: HeroSpot[] = [
  {k: 2, x: 330}, {k: 2, x: 700}, {k: 3, x: 500}, {k: 3, x: 850}, {k: 4, x: 260},
  {k: 4, x: 610}, {k: 5, x: 420}, {k: 5, x: 770}, {k: 6, x: 560}, {k: 6, x: 330},
];

// Snap hero spots onto real seats so no sleeper overlaps a hero: pass the same `spots` and `heroPan` you give Crowd and AwakeHeroes.
export const placeHeroes = (spots: HeroSpot[] = CROWD_HEROES, heroPan = 130): PlacedHero[] => spots.map((h) => {
  const t = tierOf(h.k);
  const unpanned = h.x + heroPan * Math.pow(t.size / 86, 0.8);
  const slot = Math.round((unpanned - CROWD_X0 - t.px - t.pitch / 2) / t.pitch);
  return {k: h.k, slot, x: CROWD_X0 + t.px + slot * t.pitch + t.pitch / 2};
});

// Screen x of a placed hero's feet at a given pan; the feet y is that tier's baseline (about 1320 at k 2, 1128 at k 6).
export const heroScreenX = (h: PlacedHero, pan: number) => h.x + tierShift(tierOf(h.k), pan);

// ---------- one tier: seat board behind, sleeping critters on it ----------

const Person: React.FC<{id: string; u: number; body: string; lo: string; hat: string; hatLo: string; eyes: boolean; glasses: boolean}> = ({id, u, body, lo, hat, hatLo, eyes, glasses}) => (
  <g id={id}>
    <rect x={0} y={0} width={10 * u} height={7 * u} rx={Math.min(4, 0.5 * u)} fill={lo} />
    <rect x={0} y={0} width={10 * u} height={5.9 * u} rx={Math.min(4, 0.5 * u)} fill={body} />
    <rect x={0.2 * u} y={0.2 * u} width={9.6 * u} height={0.35 * u} rx={0.15 * u} fill="#fff" opacity={0.2} />
    <path d={`M${1 * u} ${0.3 * u} A${4 * u} ${2.6 * u} 0 0 1 ${9 * u} ${0.3 * u} Z`} fill={hat} />
    <rect x={0.2 * u} y={-0.1 * u} width={9.6 * u} height={0.75 * u} rx={0.3 * u} fill={hatLo} />
    <rect x={4.6 * u} y={-2.2 * u} width={0.8 * u} height={2.2 * u} fill={hatLo} />
    {eyes ? (
      <>
        <rect x={2.85 * u} y={2.8 * u} width={1.3 * u} height={Math.max(1, 0.28 * u)} rx={0.14 * u} fill={C.ink} />
        <rect x={5.85 * u} y={2.8 * u} width={1.3 * u} height={Math.max(1, 0.28 * u)} rx={0.14 * u} fill={C.ink} />
      </>
    ) : null}
    {glasses ? (
      <>
        <circle cx={3.5 * u} cy={2.9 * u} r={1.05 * u} fill="none" stroke={C.ink} strokeWidth={0.32 * u} />
        <circle cx={6.5 * u} cy={2.9 * u} r={1.05 * u} fill="none" stroke={C.ink} strokeWidth={0.32 * u} />
      </>
    ) : null}
  </g>
);

const TierRow: React.FC<{t: Tier; shift: number; seat: string; f: number; look: Look; placed: PlacedHero[]}> = ({t, shift, seat, f, look, placed}) => {
  const u = t.size / 10;
  const depth = t.k / 24;   // 0 front -> 1 back
  const {haze} = look, tHaze = Math.min(0.62, depth * 0.7);
  const top = t.B - 11.7 * u - 2, h = 11.7 * u + 4.6 * u + (t.k === 0 ? 34 : 0);
  const detail = t.size >= 28;
  const sway = bob(f, 70 + t.k * 3, Math.min(2.6, 0.04 * t.size + 0.4), t.k * 1.7);
  // seven variants per tier: body x hat x glasses, defined once as symbols
  const variants = Array.from({length: 7}).map((_, v) => ({
    id: `p${t.k}v${v}`, body: mixHex(calm(BODY[v], look), haze, tHaze), lo: mixHex(calm(BODY_LO[v], look), haze, tHaze),
    hat: mixHex(calm(HAT[(v * 3 + t.k) % HAT.length], look), haze, tHaze), hatLo: mixHex(calm(HAT_LO[(v * 3 + t.k) % HAT.length], look), haze, tHaze), glasses: detail && t.size >= 34 && v % 3 === 1,
  }));
  const people: React.ReactNode[] = [];
  for (let i = 0; i < t.n; i++) {
    if (placed.some((p) => p.k === t.k && p.slot === i)) continue;
    const r = random(`crowd-${t.k}-${i}`);
    const v = Math.floor(r * 7);
    const dy = (random(`cy-${t.k}-${i}`) - 0.5) * 0.5 * u;
    people.push(<use key={i} href={`#${variants[v].id}`} x={t.px + i * t.pitch + (t.pitch - 10 * u) / 2} y={11.7 * u - 9.2 * u + dy + 2} />);
  }
  const svg = (
    <svg width={CROWD_W} height={h} style={{position: 'absolute', left: 0, top: 0, overflow: 'visible'}}>
      <defs>{variants.map((v) => <Person key={v.id} id={v.id} u={u} body={v.body} lo={v.lo} hat={v.hat} hatLo={v.hatLo} eyes={detail} glasses={v.glasses} />)}</defs>
      {people}
    </svg>
  );
  // seat board in front of the sleepers (covers their legs and the lowest sliver of body)
  const boardTop = 11.7 * u - 3.2 * u + 2;
  const board = <Slab x={0} y={boardTop} w={CROWD_W} h={h - boardTop} color={mixHex(seat, haze, tHaze * 0.9)} shade={mixHex('#34241C', haze, tHaze)} shadeH={0.22} hi={mixHex('#8A6548', haze, tHaze)} hiH={Math.min(0.2, 5 / (h - boardTop) + 0.01)} r={0} />;
  const box: React.CSSProperties = {position: 'absolute', left: CROWD_X0 + shift, top: top + sway, width: CROWD_W, height: h, opacity: interpolate(t.k, [15, 24], [1, 0.45], {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'})};
  return t.size >= 26 ? (
    <Paper lift={Math.max(2, t.size / 14)} style={{...box, inset: undefined}}>{svg}{board}</Paper>
  ) : (
    <div style={box}>{svg}{board}</div>
  );
};

// floating z tags over a few front sleepers
const ZZ: {k: number; slot: number}[] = [{k: 0, slot: 2}, {k: 0, slot: 8}, {k: 1, slot: 5}, {k: 1, slot: 11}, {k: 2, slot: 4}, {k: 2, slot: 10}, {k: 3, slot: 7}, {k: 3, slot: 13}];

// What a hero is doing this frame: lift (px up off the seat), expression, arms up 0-1, wave (deg), awake (true = AwakeHeroes draws it, Crowd skips it).
export type HeroState = {lift?: number; expr?: Expr; armUp?: number; awake?: boolean; wave?: number};

const HeroCritter: React.FC<{t: Tier; x: number; i: number; lift: number; expr: Expr; arm: number; seat: string; look: Look; acc: Acc; board?: boolean; wave?: number}> = ({t, x, i, lift, expr, arm, seat, look, acc, board, wave = 0}) => {
  const a = Math.max(0, Math.min(1, arm));
  const hatI = i % 3 === 0 ? 3 : 0;
  const tHaze = Math.min(0.62, (t.k / 24) * 0.7);
  return (
    <>
      <Critter x={x} y={t.B} size={t.size} color={calm(BODY[(i * 3 + 1) % 7], look)} shade={calm(BODY_LO[(i * 3 + 1) % 7], look)} acc={acc} accColor={calm(HAT[hatI], look)} accShade={calm(HAT_LO[hatI], look)}
        expr={expr} lift={lift} phase={i * 5 + 2} idle={lift > 0.5 ? false : true} armL={a * 0.6} armLAngle={-(20 + a * 55) + wave} armR={a * 0.6} armRAngle={-(20 + a * 55) - wave} />
      {/* the seat board hides the sleeper's lap; a copy sits in front of the hero so it sinks into the row when seated */}
      {board ? <Paper lift={Math.max(2, t.size / 14)} style={{inset: undefined, left: x - t.size, top: t.B - 3.2 * (t.size / 10) + 2, width: t.size * 2, height: 3.6 * (t.size / 10)}}>
        <Slab x={0} y={0} w={t.size * 2} h={3.6 * (t.size / 10)} color={mixHex(seat, look.haze, tHaze * 0.9)} r={0} hi={mixHex('#8A6548', look.haze, tHaze)} hiH={0.12} shade={mixHex('#34241C', look.haze, tHaze)} shadeH={0.2} />
      </Paper> : null}
    </>
  );
};

// The sleeping stadium, full frame. pan = px to scroll (-270..270); hero(i) = state of hero i (index into `heroes`); zz = floating z tags; seat = seat-board colour; haze/dusk = depth fog and mood tint.
export const Crowd: React.FC<{pan?: number; seat?: string; hero?: (i: number) => HeroState; zz?: boolean; heroes?: HeroSpot[]; heroPan?: number; haze?: string; dusk?: string; heroAcc?: Acc}> = ({pan = 0, seat = '#6A4A38', hero, zz = true, heroes = CROWD_HEROES, heroPan = 130, haze = '#2A2433', dusk = '#6A5A5E', heroAcc = 'hardhat'}) => {
  const f = useCurrentFrame();
  const look: Look = {haze, dusk};
  const placed = placeHeroes(heroes, heroPan);
  return (
    <>
      {TIERS.map((t) => {
        const shift = tierShift(t, pan);
        return (
          <React.Fragment key={t.k}>
            <TierRow t={t} shift={shift} seat={seat} f={f} look={look} placed={placed} />
            {placed.map((h, i) => {
              if (h.k !== t.k) return null;
              const st = hero?.(i) ?? {};
              if (st.awake) return null;
              return <HeroCritter key={i} t={t} x={h.x + shift} i={i} lift={st.lift ?? 0} expr={st.expr ?? 'sleep'} arm={st.armUp ?? 0} seat={seat} look={look} acc={heroAcc} board />;
            })}
            {zz && t.k <= 3 ? ZZ.filter((z) => z.k === t.k).map((z, j) => {
              const zx = CROWD_X0 + shift + t.px + z.slot * t.pitch + t.pitch * 0.9;
              const zy = t.B - 11.4 * (t.size / 10) - 4;
              const ph = ((f + z.slot * 9 + j * 5) % 54) / 54;
              return (
                <div key={`z${j}`} style={{position: 'absolute', left: zx, top: zy - ph * 34, fontFamily: FONT.banner, fontSize: Math.max(26, t.size * 0.4), color: '#E6EEF5', opacity: interpolate(ph, [0, 0.15, 0.75, 1], [0, 0.95, 0.8, 0]), rotate: '-8deg', textShadow: '1px 2px 0 rgba(0,0,0,0.35)', pointerEvents: 'none'}}>z</div>
              );
            }) : null}
          </React.Fragment>
        );
      })}
    </>
  );
};

// The awake heroes (hero(i).awake), drawn above everything with a brightness lift; use the same pan, seat, heroes, heroPan, haze, dusk and heroAcc as Crowd.
export const AwakeHeroes: React.FC<{hero: (i: number) => HeroState; pan?: number; seat?: string; heroes?: HeroSpot[]; heroPan?: number; haze?: string; dusk?: string; heroAcc?: Acc}> = ({pan = 0, hero, seat = '#6A4A38', heroes = CROWD_HEROES, heroPan = 130, haze = '#2A2433', dusk = '#6A5A5E', heroAcc = 'hardhat'}) => {
  const look: Look = {haze, dusk};
  const placed = placeHeroes(heroes, heroPan);
  return (
    <div style={{position: 'absolute', inset: 0, filter: 'brightness(1.14) saturate(1.18)'}}>
      {placed.map((h, i) => {
        const st = hero(i);
        if (!st.awake) return null;
        const t = tierOf(h.k);
        return <HeroCritter key={i} t={t} x={h.x + tierShift(t, pan)} i={i} lift={st.lift ?? 0} expr={st.expr ?? 'happy'} arm={st.armUp ?? 0} wave={st.wave ?? 0} seat={seat} look={look} acc={heroAcc} />;
      })}
    </div>
  );
};

// Everyday paper props that suit any episode. All paper (Slab / Disc / Pill inside <Paper>), motion only from useCurrentFrame().
//   Desk          small table with two legs and a rail, sits on a floor line
//   WallCalendar  hanging wall calendar whose month pages flip away to a big final date (+ optional pill)
//   BirthdayCake  two-tier cake on a stand with flickering candles
//   HomeSign      house-shaped enamel plaque with a word on it (default HOME)
//   Clipboard     technician's clipboard, made to ride a Critter's `holdR`
//   ThumbsUp      thumbs-up fist, made to ride a Critter's `holdR`
// Position conventions differ per prop and are in each doc line: Desk and WallCalendar take a top-left, BirthdayCake the floor point under it,
// HomeSign its middle. Clipboard and ThumbsUp are drawn around (0, 0) = the hand, so pass them as `holdR` and give `counterRot` = minus the arm's angle.
import React from 'react';
import {interpolate, useCurrentFrame} from 'remotion';
import {C, FONT} from '../tokens';
import {Disc, Paper, Pill, Slab} from '../paper/kit';

const clamp = {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'} as const;

// ---------- desk ----------

// Small paper desk. (x, y) = top-left of the table top (w wide, 34 tall); the legs run down to the y of the `floor` line. top/topLo/topHi and legs/legsLo set the wood colours.
export const Desk: React.FC<{x: number; y: number; w: number; floor: number; top?: string; topLo?: string; topHi?: string; legs?: string; legsLo?: string}> = ({x, y, w, floor, top = '#D7A56E', topLo = '#A87A4C', topHi = '#E6BC88', legs = '#B98B5A', legsLo = '#94683F'}) => (
  <Paper lift={6}>
    <Slab x={x + 36} y={y + 20} w={40} h={floor - y - 20} r={4} color={legs} shade={legsLo} shadeH={0.2} />
    <Slab x={x + w - 76} y={y + 20} w={40} h={floor - y - 20} r={4} color={legs} shade={legsLo} shadeH={0.2} />
    <Slab x={x + 60} y={y + 120} w={w - 120} h={26} r={4} color={topLo} shade={legsLo} shadeH={0.3} />
    <Slab x={x} y={y} w={w} h={34} r={8} color={top} hi={topHi} hiH={0.3} shade={topLo} shadeH={0.25} />
  </Paper>
);

// ---------- wall calendar ----------

const DAYS = 7, WEEKS = 5;
const MonthGrid: React.FC<{w: number; h: number; top: number; tint: string; marks?: number[]}> = ({w, h, top, tint, marks = []}) => {
  const cw = (w - 40) / DAYS, ch = (h - top - 26) / WEEKS;
  return (
    <>
      {Array.from({length: DAYS * WEEKS}).map((_, i) => {
        const c = i % DAYS, r = Math.floor(i / DAYS);
        return <Slab key={i} x={20 + c * cw + 3} y={top + 8 + r * ch + 3} w={cw - 6} h={ch - 6} r={4} color={marks.includes(i) ? '#E7A39A' : tint} />;
      })}
    </>
  );
};

// One month page that flips away: its month word and the day-cell indexes (0-34) to mark in red.
export type CalendarPage = {month: string; marks?: number[]};

// Hanging wall calendar, w x h at (x, y) = top-left of the sheet (nail and string reach 58 px above). `pages` flip up and away one every `flipEvery` frames from `flipAt`, first page first, then the `final` page shows a huge day and an optional pill `label`. bump 0-1 pops it.
export const WallCalendar: React.FC<{x: number; y: number; flipAt: number; w?: number; h?: number; flipEvery?: number; rot?: number; bump?: number; pages?: CalendarPage[]; final?: {month: string; day: string; label?: string}; head?: string; headLo?: string; labelBg?: string}> = ({
  x, y, flipAt, w = 300, h = 340, flipEvery = 4, rot = -2.5, bump = 0, pages = [{month: 'JAN'}, {month: 'FEB', marks: [11, 12]}], final = {month: 'MAR', day: '1'}, head = '#C9573C', headLo = '#A6422B', labelBg = C.tag,
}) => {
  const f = useCurrentFrame();
  const headH = 74;
  const flipOf = (i: number) => interpolate(f, [flipAt + i * flipEvery, flipAt + i * flipEvery + 4], [0, 1], clamp);
  const endAt = flipAt + pages.length * flipEvery;
  const landed = interpolate(f, [endAt - 1, endAt + 2, endAt + 8], [0, 1, 0], clamp);
  const sheet = (month: string, children: React.ReactNode, key: string, extra?: React.CSSProperties) => (
    <Slab key={key} x={0} y={0} w={w} h={h} r={6} color="#F4EFE5" shade="#DAD2C2" shadeH={0.02} style={extra}>
      <Slab x={0} y={0} w={w} h={headH} r="6px 6px 0 0" color={head} shade={headLo} shadeH={0.12}>
        <div style={{position: 'absolute', inset: 0, display: 'grid', placeItems: 'center', fontFamily: FONT.banner, fontSize: 40, color: C.tagText, letterSpacing: '0.08em'}}>{month}</div>
      </Slab>
      {children}
    </Slab>
  );
  return (
    <div style={{position: 'absolute', left: x, top: y, width: w, height: h, rotate: `${rot}deg`, scale: String(1 + 0.08 * bump + 0.04 * landed), transformOrigin: '50% 0'}}>
      <Paper lift={7}>
        {/* string and nail */}
        <Slab x={w / 2 - 3} y={-52} w={6} h={56} r={3} color="#8A7A5C" />
        <Disc x={w / 2} y={-58} d={22} color={C.metal} shade={C.metalLo} />
        {/* the final page sits at the bottom of the stack */}
        {sheet(final.month, (
          <>
            <div style={{position: 'absolute', left: 0, right: 0, top: headH + 4, textAlign: 'center', fontFamily: FONT.banner, fontSize: Math.round(h * 0.44), lineHeight: 1.1, color: C.ink}}>{final.day}</div>
            {final.label ? <Pill x={w / 2} y={h - 62} text={final.label} bg={labelBg} color={C.tagText} size={32} center rot={-3} /> : null}
          </>
        ), 'final')}
        {pages.map((_, n) => pages.length - 1 - n).map((i) => {
          const p = pages[i];
          const u = flipOf(i);   // page 0 is on top (drawn last) and flips first
          if (u >= 1) return null;
          return sheet(p.month, <MonthGrid w={w} h={h} top={headH} tint="#DDD6C8" marks={p.marks} />, `p${i}`, {
            transformOrigin: '50% 0', scale: `1 ${Math.max(0.02, 1 - u * 1.05)}`, rotate: `${-u * 5}deg`, translate: `0 ${-u * 14}px`,
            opacity: 1 - Math.max(0, u - 0.8) * 5,
          });
        })}
      </Paper>
    </div>
  );
};

// ---------- birthday cake ----------

// Two-tier cake on a stand, about 330 px wide and 320 tall at s = 1. (x, y) = the floor point under the stand; `candles` (up to about 12) are spaced across the top tier; lit = flames on. color/colorLo = pink tier, topColor/topLo = cream tier.
export const BirthdayCake: React.FC<{x: number; y: number; s?: number; candles?: number; lit?: boolean; color?: string; colorLo?: string; topColor?: string; topLo?: string}> = ({x, y, s = 1, candles = 10, lit = true, color = '#E9A1B4', colorLo = '#CB7F95', topColor = '#F4E4C8', topLo = '#D9C39B'}) => {
  const f = useCurrentFrame();
  const candleCols = ['#6FA8DC', '#F4A7B9', '#F5C542', '#8FD0A0'];
  const cxOf = (i: number) => (candles > 1 ? -81 + (i * 162) / (candles - 1) : 0);
  return (
    <div style={{position: 'absolute', left: x, top: y, width: 0, height: 0, scale: String(s), transformOrigin: '0 0'}}>
      <Paper lift={6}>
        {/* stand: foot, stem, plate */}
        <Slab x={-70} y={-16} w={140} h={16} r={8} color="#E9E1D2" shade="#C9BFAB" shadeH={0.4} />
        <Slab x={-18} y={-76} w={36} h={64} r={6} color="#E9E1D2" shade="#C9BFAB" shadeH={0.3} />
        <Slab x={-165} y={-98} w={330} h={26} r={13} color="#F2EBDD" shade="#CFC4AE" shadeH={0.4} hi="#FBF7EE" hiH={0.25} />
        {/* bottom tier with a frosting edge */}
        <Slab x={-125} y={-188} w={250} h={94} r="14px 14px 8px 8px" color={color} shade={colorLo} shadeH={0.2} hi="#F2BCCB" hiH={0.14} />
        <Slab x={-125} y={-188} w={250} h={26} r="14px 14px 0 0" color="#FBF3E6" />
        {[-100, -62, -20, 22, 64, 98].map((dx, i) => <Slab key={i} x={dx - 11} y={-170} w={22} h={22 + (i % 3) * 10} r={11} color="#FBF3E6" />)}
        {/* top tier */}
        <Slab x={-88} y={-244} w={176} h={62} r="12px 12px 4px 4px" color={topColor} shade={topLo} shadeH={0.2} hi="#FBF1DD" hiH={0.14} />
        <Slab x={-88} y={-244} w={176} h={20} r="12px 12px 0 0" color={color} />
        {/* candles */}
        {Array.from({length: candles}).map((_, i) => (
          <Slab key={i} x={cxOf(i) - 4} y={-282} w={8} h={40} r={3} color={candleCols[i % 4]} shade="rgba(0,0,0,0.18)" shadeH={0.3} />
        ))}
      </Paper>
      {/* flames: warm glow plus a flickering paper teardrop on each candle */}
      {lit ? Array.from({length: candles}).map((_, i) => {
        const cx = cxOf(i);
        const fl = 0.85 + 0.25 * Math.sin(f * 0.9 + i * 1.7);
        return (
          <React.Fragment key={i}>
            <div style={{position: 'absolute', left: cx - 15, top: -321, width: 30, height: 36, borderRadius: '50%', background: 'radial-gradient(circle, rgba(255,214,120,0.55), rgba(255,214,120,0))', mixBlendMode: 'screen'}} />
            <Slab x={cx - 6} y={-306 - 2 * fl} w={12} h={22 * fl} r={6} color="#F7B23B" style={{clipPath: 'polygon(50% 0, 100% 62%, 78% 100%, 22% 100%, 0 62%)'}}>
              <Slab x={3} y={8 * fl} w={6} h={11 * fl} r={3} color="#FFE9A8" />
            </Slab>
          </React.Fragment>
        );
      }) : null}
    </div>
  );
};

