      </Slab>
      <div style={{position: 'absolute', left: 124, right: 10, top: 0, bottom: 0, display: 'flex', alignItems: 'center', fontFamily: FONT.label, fontWeight: 800, fontSize: Math.min(40, (w - 140) / (name.length * 0.62)), color: C.ink}}>{name}</div>
    </Slab>
